expected_functions:='[{"name": "private.active_admin_user", "signature": "uuid,uuid", "body": "\n  select p_user is not null and p_session is not null and exists(\n    select 1 from auth.users u join auth.sessions a on a.user_id=u.id\n    join private.admin_memberships m on m.user_id=u.id and m.active\n    where u.id=p_user and a.id=p_session and u.deleted_at is null\n    and (u.banned_until is null or u.banned_until<=now())\n    and u.raw_app_meta_data->>''app_role''=''admin''\n    and (a.not_after is null or a.not_after>now())\n  )\n", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "86ee931af6f7fa948cecc015793266d458766640e80a4df5dc34ce70998a3530"}, {"name": "private.assert_editor", "signature": "", "body": "\nbegin\n  if not private.is_admin() and private.caller_role() not in (''postgres'',''supabase_admin'',''service_role'') then raise exception ''EDITOR_ONLY'' using errcode=''42501''; end if;\nend", "securityDefiner": false, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "665df337b253f85b38455e99abaddda0cdaeb791eee032d003d6f4bfc09faa2e"}, {"name": "private.assert_initialized", "signature": "", "body": "\nbegin\n if (select count(*) from private.runtime_identity)<>1 or not exists(select 1 from private.runtime_identity where singleton and product_id=''judoju-news'' and environment=''preview'' and bootstrap_id is null and schema_version=1)\n or (select count(*) from judoju_control.environment_identity)<>1 or not exists(select 1 from judoju_control.environment_identity where singleton and product_id=''judoju-news'' and environment=''dev'' and organization_ref=''qfzgicohgpuogehdyzfx'' and project_ref=''nxfpfvsdwbziowkxsxnh'')\n or not exists(select 1 from judoju_control.schema_artifacts where version=''20261114000001'' and project_ref=''nxfpfvsdwbziowkxsxnh'' and runtime_environment=''preview'' and source_sha256=''5b3c2d38206dc3c43c51db287d14584b3aa72b1f54d5b2e368e252a5fcf90caa'' and state=''STAGED_DISABLED'') then raise exception ''CLOUD_PRODUCT_NOT_INITIALIZED'';end if;\nend", "securityDefiner": false, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "1678222a98b7fdfa34c8041ec7905adfa9c3e1ba85129c4912219c48abd9b231"}, {"name": "private.assert_installation", "signature": "uuid,text,int", "body": "\nbegin\n  if p_secret is null or length(p_secret)<>64 or not exists(select 1 from private.installations where id=p_install and secret_version=p_version and revoked_at is null and expires_at>clock_timestamp() and secret_hash=extensions.digest(convert_to(p_secret,''UTF8''),''sha256'')) then raise exception ''INSTALLATION_UNAUTHORIZED'' using errcode=''42501'';end if;\nend", "securityDefiner": false, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "692079a447cbaae8100835751ae8b8215a468b7e1ce6403908cb2284dbe5e3a4"}, {"name": "private.assert_server", "signature": "", "body": "\nbegin\n  if private.caller_role() not in (''postgres'',''supabase_admin'',''service_role'') then raise exception ''SERVER_ONLY'' using errcode=''42501''; end if;\nend", "securityDefiner": false, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "813f3d2ad73bc536d43afc7dc910bf8f3504c8e18c23f6a9b0a062b5f17de068"}, {"name": "private.caller_role", "signature": "", "body": "\n  select coalesce(nullif(current_setting(''request.jwt.claims'',true),'''')::jsonb->>''role'',nullif(current_setting(''role'',true),''none''),session_user)\n", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "990dc3c85189d49379613761a2897631608244ab990fa6eef2f736c653196c51"}, {"name": "private.is_admin", "signature": "", "body": "\ndeclare c jsonb;u uuid;s uuid;\nbegin\n  if private.caller_role()<>''authenticated'' then return false;end if;\n  c:=coalesce(nullif(current_setting(''request.jwt.claims'',true),''''),''{}'')::jsonb;\n  if coalesce(c->>''sub'','''')!~''^[0-9a-f-]{36}$'' or coalesce(c->>''session_id'','''')!~''^[0-9a-f-]{36}$'' then return false;end if;\n  begin u:=(c->>''sub'')::uuid;s:=(c->>''session_id'')::uuid;exception when invalid_text_representation then return false;end;\n  return private.active_admin_user(u,s) and exists(select 1 from private.admin_sessions x\n    where x.user_id=u and x.auth_session_id=s and x.revoked_at is null and x.expires_at>now());\nend", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "ec45d50f359553ed5a26de648f96350d372dae1205e78a271edee14dd3e54a3a"}, {"name": "private.m0_get_public_article_legacy", "signature": "uuid", "body": "\ndeclare r jsonb;p public.news_public;v private.article_versions;sections text[];\nbegin\n  r:=public.resolve_issue(p_issue);\n  if r->>''state''<>''PUBLISHED'' then return r;end if;\n  select * into p from public.news_public where issue_id=(r->>''canonical_issue_id'')::uuid and publication_state=''PUBLISHED'';\n  if not found then return jsonb_build_object(''state'',''NOT_FOUND'',''message'',''현재 제공하지 않는 글'');end if;\n  select * into strict v from private.article_versions where id=p.version_id and issue_id=p.issue_id;\n  sections:=private.visible_sections(v.impact_profile,v.public_body,v.evidence_as_of,now());\n  return jsonb_build_object(''issue_id'',p.issue_id,''version_id'',p.version_id,''state'',p.publication_state,''title'',p.title,''summary'',p.summary,''body'',private.public_body(v.public_body,sections,now()),''first_published_at'',p.first_published_at,''material_change_at'',p.material_change_at,''sample_kind'',p.sample_kind);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "7e038695b3db9db5e4dac09b38a12f2260bcde5c84a926671c1dc70870ccd48a"}, {"name": "private.m0_public_body", "signature": "jsonb,text[],timestamptz", "body": "\ndeclare result jsonb;\nbegin\n  result:=jsonb_build_object(''key_issues'',coalesce(p_body->''key_issues'',''[]''),''issue_analysis'',coalesce(p_body->''issue_analysis'',''\"\"''),''sources'',coalesce(p_body->''sources'',''[]''),''visible_sections'',p_sections);\n  if ''SCENARIOS''=any(p_sections) then result:=result||jsonb_build_object(''scenarios'',p_body->''scenarios'');end if;\n  if ''BENEFIT_SECTORS''=any(p_sections) then result:=result||jsonb_build_object(''benefit_sector_ids'',p_body->''benefit_sector_ids'');end if;\n  if ''DAMAGE_SECTORS''=any(p_sections) then result:=result||jsonb_build_object(''damage_sector_ids'',p_body->''damage_sector_ids'');end if;\n  if ''RELATED_SECTORS''=any(p_sections) then result:=result||jsonb_build_object(''related_sector_ids'',p_body->''related_sector_ids'');end if;\n  if ''RISKS''=any(p_sections) then result:=result||jsonb_build_object(''risks'',p_body->''risks'');end if;\n  if ''SCHEDULE''=any(p_sections) then result:=result||jsonb_build_object(''schedule'',(select jsonb_agg(x) from jsonb_array_elements(p_body->''schedule'') x where (x->>''event_at'')::timestamptz>p_now));end if;\n  return result;\nend", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "e6e865c8c61a2acf3b25241d88be5824f5a2b127ea7524a8ca093f573441238e"}, {"name": "private.m0_publish_legacy", "signature": "uuid,bigint,text,text,jsonb,text,bigint,bigint,text", "body": "\ndeclare i private.issues;v_id uuid:=gen_random_uuid();sections text[];claim private.claims;independent_three boolean;sector uuid;request_hash text;\nbegin\n  perform private.assert_editor();perform private.assert_initialized();\n  if p_effect_key is null or length(p_effect_key) not between 1 and 200 then raise exception ''EFFECT_KEY_REQUIRED'';end if;\n  request_hash:=encode(extensions.digest(convert_to(jsonb_build_object(''issue'',p_issue,''expected_revision'',p_expected_revision,''title'',p_title,''summary'',p_summary,''body'',p_body,''profile'',p_profile,''policy'',p_policy,''catalog'',p_catalog)::text,''UTF8''),''sha256''),''hex'');\n  select * into strict i from private.issues where id=p_issue for update;\n  if exists(select 1 from private.outbox where effect_key=p_effect_key and issue_id=p_issue) then\n    if not exists(select 1 from private.outbox where effect_key=p_effect_key and payload->>''request_hash''=request_hash) then raise exception ''EFFECT_PAYLOAD_CONFLICT'';end if;\n    return jsonb_build_object(''status'',''ALREADY_APPLIED'',''issue_id'',i.id,''revision'',i.revision,''version_id'',i.current_version_id);\n  end if;\n  if exists(select 1 from private.outbox where effect_key=p_effect_key) then raise exception ''EFFECT_KEY_CONFLICT'';end if;\n  if i.revision is distinct from p_expected_revision then raise exception ''REVISION_CONFLICT'' using errcode=''40001'';end if;\n  if i.publication_state in (''HIDDEN'',''WITHDRAWN'') then raise exception ''NO_AUTOMATIC_REPUBLISH'';end if;\n  if i.scheduled_publish_at is not null and i.scheduled_publish_at>now() then raise exception ''SCHEDULE_NOT_DUE'';end if;\n  if not exists(select 1 from private.policies where version=p_policy and active) or not exists(select 1 from private.catalog_versions where version=p_catalog and active) then raise exception ''STALE_POLICY_OR_CATALOG'';end if;\n  if i.sample_kind<>''SYNTHETIC'' then raise exception ''REAL_PUBLICATION_NOT_ENABLED_STAGE_4'';end if;\n  if not exists(select 1 from private.runtime_identity where environment=''preview'') then raise exception ''SYNTHETIC_PUBLICATION_FORBIDDEN'';end if;\n  if i.primary_sector_id is not null and not exists(select 1 from private.sectors where id=i.primary_sector_id and active and catalog_version=p_catalog) then raise exception ''PRIMARY_SECTOR_INACTIVE'';end if;\n  if not exists(select 1 from private.claims where issue_id=i.id) then raise exception ''CLAIM_REQUIRED'';end if;\n  for claim in select * from private.claims where issue_id=i.id loop\n    if not claim.verified or not claim.korea_path_verified or not claim.fact_current or claim.valid_until is not null and claim.valid_until<=now() or claim.claim_type=''SENSITIVE_UNCONFIRMED'' then raise exception ''CLAIM_NOT_VERIFIED'';end if;\n    if claim.claim_type=''SYSTEMIC_MACRO'' and not claim.official_original then\n      select exists(select 1 from private.evidence_edges a join private.evidence_edges b on a.claim_id=b.claim_id and a.id<b.id join private.evidence_edges c on b.claim_id=c.claim_id and b.id<c.id\n        where a.claim_id=claim.id\n        and a.origin_verified and a.newsroom_verified and a.owner_group_verified and a.independent_fact_verified\n        and b.origin_verified and b.newsroom_verified and b.owner_group_verified and b.independent_fact_verified\n        and c.origin_verified and c.newsroom_verified and c.owner_group_verified and c.independent_fact_verified\n        and a.origin_group_id<>b.origin_group_id and b.origin_group_id<>c.origin_group_id and a.origin_group_id<>c.origin_group_id\n        and a.newsroom_id<>b.newsroom_id and b.newsroom_id<>c.newsroom_id and a.newsroom_id<>c.newsroom_id\n        and a.owner_group_id<>b.owner_group_id and b.owner_group_id<>c.owner_group_id and a.owner_group_id<>c.owner_group_id\n      ) into independent_three;\n      if not independent_three then raise exception ''MACRO_INDEPENDENT_THREE_REQUIRED'';end if;\n    end if;\n  end loop;\n  sections:=private.visible_sections(p_profile,p_body,now(),now());\n  for sector in select value::text::uuid from jsonb_array_elements_text(coalesce(p_body->''benefit_sector_ids'',''[]'')||coalesce(p_body->''damage_sector_ids'',''[]'')||coalesce(p_body->''related_sector_ids'',''[]'')) loop\n    if not exists(select 1 from private.sectors where id=sector and active and catalog_version=p_catalog) then raise exception ''IMPACT_SECTOR_INACTIVE'';end if;\n  end loop;\n  insert into private.article_versions(id,issue_id,title,summary,public_body,source_market,selection_market_basis,analysis_perspective,impact_profile,visibility_policy_version,catalog_version,evidence_as_of,visible_sections)\n  values(v_id,i.id,p_title,p_summary,p_body,coalesce(p_body->>''source_market'',''SYNTHETIC''),coalesce(p_body->>''selection_market_basis'',''KR''),''KR_EQUITY'',p_profile,p_policy,p_catalog,now(),sections);\n  insert into private.impacts(version_id,sector_id,direction,path_id,conditions)\n    select v_id,x::uuid,''BENEFIT'',''SYNTHETIC'', ''[]''::jsonb from jsonb_array_elements_text(coalesce(p_body->''benefit_sector_ids'',''[]'')) x\n    union all select v_id,x::uuid,''DAMAGE'',''SYNTHETIC'',''[]''::jsonb from jsonb_array_elements_text(coalesce(p_body->''damage_sector_ids'',''[]'')) x\n    union all select v_id,x::uuid,''RELATED'',''SYNTHETIC'',''[\"조건부\"]''::jsonb from jsonb_array_elements_text(coalesce(p_body->''related_sector_ids'',''[]'')) x;\n  update private.issues set current_version_id=v_id,publication_state=''PUBLISHED'',first_published_at=coalesce(first_published_at,now()),material_change_at=now(),revision=revision+1 where id=i.id;\n  insert into private.outbox(issue_id,version_id,event_type,effect_key,payload) values(i.id,v_id,''ISSUE_PUBLISHED'',p_effect_key,jsonb_build_object(''issue_id'',i.id,''version_id'',v_id,''sample_kind'',''SYNTHETIC'',''request_hash'',request_hash));\n  return jsonb_build_object(''status'',''APPLIED'',''issue_id'',i.id,''revision'',i.revision+1,''version_id'',v_id,''visible_sections'',sections);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "f7a1b9b890f9ca38b353ea64cda6140adba4a720f1b1004b629bd20a93e76212"}, {"name": "private.m0_visible_sections", "signature": "text,jsonb,timestamptz,timestamptz", "body": "\ndeclare result text[]:=array[''KEY_ISSUES'',''ISSUE_ANALYSIS'']; positive_count integer;negative_count integer;\nbegin\n  if p_profile not in (''POSITIVE_ONLY'',''POSITIVE_NEGATIVE'',''DAMAGE_ONLY'',''RELATED_CONDITIONAL'') then raise exception ''UNKNOWN_IMPACT_PROFILE''; end if;\n  if jsonb_typeof(p_body)<>''object'' then raise exception ''BODY_OBJECT_REQUIRED''; end if;\n  select count(*) filter(where x->>''direction''=''POSITIVE''),count(*) filter(where x->>''direction''=''NEGATIVE'') into positive_count,negative_count from jsonb_array_elements(coalesce(p_body->''scenarios'',''[]'')) x;\n  if p_profile=''DAMAGE_ONLY'' then\n    if jsonb_array_length(coalesce(p_body->''risks'',''[]''))=0 then raise exception ''DAMAGE_REQUIRES_RISKS''; end if;\n    if positive_count+negative_count>0 then raise exception ''DAMAGE_ONLY_NO_SCENARIO''; end if;\n  else\n    if positive_count<1 or p_profile=''POSITIVE_ONLY'' and negative_count>0 or p_profile=''POSITIVE_NEGATIVE'' and negative_count<1 then raise exception ''SCENARIO_PROFILE_MISMATCH''; end if;\n    result:=array_append(result,''SCENARIOS'');\n  end if;\n  if jsonb_array_length(coalesce(p_body->''benefit_sector_ids'',''[]''))>0 then\n    if p_profile in (''DAMAGE_ONLY'',''RELATED_CONDITIONAL'') then raise exception ''BENEFIT_NOT_ESTABLISHED''; end if;\n    result:=array_append(result,''BENEFIT_SECTORS'');\n  end if;\n  if jsonb_array_length(coalesce(p_body->''damage_sector_ids'',''[]''))>0 then\n    if p_profile in (''POSITIVE_ONLY'',''RELATED_CONDITIONAL'') then raise exception ''DAMAGE_NOT_ESTABLISHED''; end if;\n    result:=array_append(result,''DAMAGE_SECTORS'');\n  end if;\n  if jsonb_array_length(coalesce(p_body->''related_sector_ids'',''[]''))>0 then result:=array_append(result,''RELATED_SECTORS''); end if;\n  if p_profile=''DAMAGE_ONLY'' and not ''DAMAGE_SECTORS''=any(result) then raise exception ''DAMAGE_SECTOR_REQUIRED''; end if;\n  if p_profile=''RELATED_CONDITIONAL'' and not ''RELATED_SECTORS''=any(result) then raise exception ''RELATED_SECTOR_REQUIRED''; end if;\n  if jsonb_array_length(coalesce(p_body->''risks'',''[]''))>0 then result:=array_append(result,''RISKS''); end if;\n  if exists(select 1 from jsonb_array_elements(coalesce(p_body->''schedule'',''[]'')) x where (x->>''event_at'')::timestamptz>greatest(p_as_of,p_now)) then result:=array_append(result,''SCHEDULE''); end if;\n  return array_append(result,''SOURCES'');\nend", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "ce4755c9c7261d65cf2d2f87cb911915460cedfdeb46b2d69856599c697167a3"}, {"name": "private.m1_assert_editor", "signature": "", "body": "\nbegin perform private.assert_initialized();if not private.is_admin() then raise exception ''EDITOR_ONLY'' using errcode=''42501'';end if;end", "securityDefiner": false, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "0335319bc349f5eec5b747e9e17e5fb249d5a34ab9aa176ac227192a3f18212c"}, {"name": "private.m1_body_issue", "signature": "jsonb", "body": "\n select coalesce(nullif(p_body->>''_issue_id'','''')::uuid,(select c.issue_id from jsonb_array_elements(coalesce(p_body->''impacts'',''[]'')) x\n cross join lateral jsonb_array_elements_text(coalesce(x->''evidence_ids'',''[]'')) e(id)\n join private.claims c on c.id=e.id::uuid limit 1))\n", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "e1fcffb388e143e2a4d323060811440e53cf3327f18887abb0208f1f8fca1c48"}, {"name": "private.m1_claim_allowed", "signature": "uuid,uuid,boolean,boolean", "body": "\n select exists(select 1 from private.claims c where c.id=p_claim and c.issue_id=p_issue\n and c.verified and c.fact_current and c.korea_path_verified and c.claim_type<>''SENSITIVE_UNCONFIRMED''\n and (c.valid_until is null or c.valid_until>now())\n and (not p_official or c.official_original)\n and (not(p_macro or c.claim_type=''SYSTEMIC_MACRO'') or c.official_original or private.m1_independent_three(c.id)))\n", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "399d3102065ed0022c4c94db91cc92f752d74f30f00370e31bdc55bbf10a7646"}, {"name": "private.m1_core_evidence", "signature": "uuid,text", "body": "\n select exists(select 1 from private.claims where issue_id=p_issue)\n and not exists(select 1 from private.claims c where c.issue_id=p_issue and not private.m1_claim_allowed(c.id,p_issue,p_kind=''MACRO'',false))\n", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "1120b53493bef544c3de3dc5c6e4d8c380693ee472d9c9de51487b479b7172a6"}, {"name": "private.m1_current_evidence", "signature": "uuid", "body": "\n select private.m1_current_evidence_v2(p_issue) and exists(select 1 from private.issues i join private.article_versions v on v.id=i.current_version_id\n where i.id=p_issue and private.m1_core_evidence(i.id,v.public_body->>''article_kind''))\n", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "d1b49a7092fbf76ff09ddcbe0c2df6a6653fd0b20228cddd5a788d3a262e492d"}, {"name": "private.m1_current_evidence_v1", "signature": "uuid", "body": "\n  select exists(select 1 from private.issues i join private.article_versions v on v.id=i.current_version_id\n    where i.id=p_issue and i.publication_state=''PUBLISHED'' and i.sample_kind=''SYNTHETIC'' and v.public_body->>''_contract''=''M1''\n    and exists(select 1 from private.policies p where p.version=v.visibility_policy_version and p.active)\n    and exists(select 1 from private.catalog_versions c where c.version=v.catalog_version and c.active)\n    and exists(select 1 from private.impacts z where z.version_id=v.id)\n    and not exists(select 1 from private.claims c where c.issue_id=i.id and (not c.verified or not c.fact_current or not c.korea_path_verified or c.claim_type=''SENSITIVE_UNCONFIRMED'' or c.valid_until<=now()))\n    and not exists(select 1 from private.impacts z left join private.sectors s on s.id=z.sector_id where z.version_id=v.id and (not s.active or s.catalog_version<>v.catalog_version))\n  )\n", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "170712bdc0699005a2701ec1e5db73c485e218bb87b596f5beb8d9065f6217b7"}, {"name": "private.m1_current_evidence_v2", "signature": "uuid", "body": "\n select private.m1_current_evidence_v1(p_issue)\n and not exists(select 1 from private.issues i left join private.sectors s on s.id=i.primary_sector_id where i.id=p_issue and i.primary_sector_id is not null and (s.id is null or not s.active))\n and not exists(select 1 from private.issues i join private.impacts z on z.version_id=i.current_version_id cross join lateral unnest(z.evidence_ids) e(id)\n   left join private.claims c on c.id=e.id and c.issue_id=i.id where i.id=p_issue and (c.id is null or not c.verified or not c.fact_current or not c.korea_path_verified or c.valid_until<=now()))\n", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "9aa286dea1206af980f76af525a054d18114216af500c99824f7d51919dcc42f"}, {"name": "private.m1_draft_shape", "signature": "jsonb", "body": "\ndeclare k text;x jsonb;y jsonb;\nbegin\n if p_content is null or jsonb_typeof(p_content)<>''object'' or pg_column_size(p_content)>131072 then raise exception ''DRAFT_SHAPE_INVALID'';end if;\n foreach k in array array[''title'',''summary'',''article_kind'',''source_market'',''selection_market_basis'',''analysis_perspective'',''issue_analysis''] loop\n   if jsonb_typeof(p_content->k) is distinct from ''string'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;\n end loop;\n if not p_content ? ''primary_sector_id'' or jsonb_typeof(p_content->''primary_sector_id'') not in (''string'',''null'') then raise exception ''DRAFT_SHAPE_INVALID'';end if;\n foreach k in array array[''key_issues'',''risks'',''sources'',''impacts'',''scenarios'',''schedule''] loop\n   if jsonb_typeof(p_content->k) is distinct from ''array'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;\n end loop;\n for x in select value from jsonb_array_elements(p_content->''key_issues'') union all select value from jsonb_array_elements(p_content->''risks'') loop\n   if jsonb_typeof(x)<>''string'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;\n end loop;\n for x in select value from jsonb_array_elements(p_content->''sources'') loop\n   if jsonb_typeof(x->''name'') is distinct from ''string'' or jsonb_typeof(x->''url'') is distinct from ''string'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;\n end loop;\n for x in select value from jsonb_array_elements(p_content->''impacts'') loop\n   foreach k in array array[''sector_id'',''path_id'',''direction'',''conditional_direction'',''description''] loop if jsonb_typeof(x->k) is distinct from ''string'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;end loop;\n   foreach k in array array[''conditions'',''evidence_ids''] loop\n     if jsonb_typeof(x->k) is distinct from ''array'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;\n     for y in select value from jsonb_array_elements(x->k) loop if jsonb_typeof(y)<>''string'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;end loop;\n   end loop;\n end loop;\n for x in select value from jsonb_array_elements(p_content->''scenarios'') loop\n   foreach k in array array[''direction'',''title'',''expected_result''] loop if jsonb_typeof(x->k) is distinct from ''string'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;end loop;\n   foreach k in array array[''checks'',''path_ids''] loop\n     if jsonb_typeof(x->k) is distinct from ''array'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;\n     for y in select value from jsonb_array_elements(x->k) loop if jsonb_typeof(y)<>''string'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;end loop;\n   end loop;\n end loop;\n for x in select value from jsonb_array_elements(p_content->''schedule'') loop\n   foreach k in array array[''kind'',''status'',''title'',''timezone'',''evidence_as_of''] loop if jsonb_typeof(x->k) is distinct from ''string'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;end loop;\n   if x->>''kind''=''EXACT'' then\n     if jsonb_typeof(x->''event_at'') is distinct from ''string'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;\n   elsif x->>''kind''=''PERIOD'' then\n     foreach k in array array[''period_label'',''period_start'',''period_end'',''precision''] loop if jsonb_typeof(x->k) is distinct from ''string'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;end loop;\n   else raise exception ''DRAFT_SHAPE_INVALID'';end if;\n   if jsonb_typeof(x->''evidence_ids'') is distinct from ''array'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;\n   for y in select value from jsonb_array_elements(x->''evidence_ids'') loop if jsonb_typeof(y)<>''string'' then raise exception ''DRAFT_SHAPE_INVALID'';end if;end loop;\n end loop;\nend", "securityDefiner": false, "volatility": "i", "config": ["search_path=\"\""], "definitionSha256": "276b8bebe28a17b93e28421701a1ff3a87be5b524e01d5af90dfdecf9891527e"}, {"name": "private.m1_independent_three", "signature": "uuid", "body": "\n select exists(select 1 from private.evidence_edges a\n join private.evidence_edges b on a.claim_id=b.claim_id and a.id<b.id\n join private.evidence_edges c on b.claim_id=c.claim_id and b.id<c.id\n where a.claim_id=p_claim\n and a.origin_verified and a.newsroom_verified and a.owner_group_verified and a.independent_fact_verified\n and b.origin_verified and b.newsroom_verified and b.owner_group_verified and b.independent_fact_verified\n and c.origin_verified and c.newsroom_verified and c.owner_group_verified and c.independent_fact_verified\n and a.origin_group_id<>b.origin_group_id and b.origin_group_id<>c.origin_group_id and a.origin_group_id<>c.origin_group_id\n and a.newsroom_id<>b.newsroom_id and b.newsroom_id<>c.newsroom_id and a.newsroom_id<>c.newsroom_id\n and a.owner_group_id<>b.owner_group_id and b.owner_group_id<>c.owner_group_id and a.owner_group_id<>c.owner_group_id)\n", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "cc3c7d8667a39b8d6bd5555fa3ecaeef5b34ff1753cd7601990e42a62f3fc825"}, {"name": "private.m1_live_schedule", "signature": "jsonb,timestamptz", "body": "\n select coalesce(jsonb_agg(case when x->>''kind''=''EXACT'' then jsonb_build_object(''kind'',''EXACT'',''title'',x->>''title'',''event_at'',x->>''event_at'',''timezone'',x->>''timezone'')\n else jsonb_strip_nulls(jsonb_build_object(''kind'',''PERIOD'',''title'',x->>''title'',''period_label'',x->>''period_label'',''date_note'',case when x->>''precision''=''DATE_RANGE'' then null else ''정확한 날짜 미정'' end,''timezone'',x->>''timezone'')) end),''[]'')\n from jsonb_array_elements(coalesce(p_body->''schedule'',''[]'')) x\n where case when x->>''status''<>''VERIFIED'' then false\n when x->>''kind''=''EXACT'' then (x->>''event_at'')::timestamptz>p_now\n when x->>''kind''=''PERIOD'' then (x->>''period_end'')::timestamptz>p_now else false end\n and jsonb_array_length(coalesce(x->''evidence_ids'',''[]''))>0\n and not exists(select 1 from jsonb_array_elements_text(x->''evidence_ids'') e(id)\n where not private.m1_claim_allowed(e.id::uuid,private.m1_body_issue(p_body),false,true))\n", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "10cdf67644e0c6c6174fcbc6a3a1a3fb273047f293d3692a8d8d6526dc9e8722"}, {"name": "private.m1_prepare", "signature": "uuid,jsonb,bigint,bigint", "body": "\nbegin\n if not private.m1_core_evidence(p_issue,coalesce(p_input->>''article_kind'','''')) then raise exception ''CLAIM_NOT_VERIFIED'';end if;\n return private.m1_prepare_v4(p_issue,p_input,p_policy,p_catalog)||jsonb_build_object(''_issue_id'',p_issue);\nend", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "4ffd7bc62c628fa5103f791cc3873e46b34fe2f9d66b7df907b2e30d0565ff54"}, {"name": "private.m1_prepare_v1", "signature": "uuid,jsonb,bigint,bigint", "body": "\ndeclare b jsonb:=p_input;x jsonb;e uuid;sector uuid;path text;direction text;cd text;positive text[]:=''{}'';negative text[]:=''{}'';\n  benefit jsonb:=''[]'';damage jsonb:=''[]'';related jsonb:=''[]'';all_sectors jsonb:=''[]'';impacts jsonb:=''[]'';scenarios jsonb;profile text;\n  pos_count integer;neg_count integer;title text;valid boolean;seen text[]:=''{}'';key text;schedules jsonb:=''[]'';kind text;tz text;start_at timestamptz;end_at timestamptz;\nbegin\n  if b is null or jsonb_typeof(b)<>''object'' or pg_column_size(b)>131072 then raise exception ''INVALID_EDITOR_CONTENT'';end if;\n  if b ? ''scheduled_publish_at'' or b ? ''sample_kind'' and b->>''sample_kind''<>''SYNTHETIC'' then raise exception ''RESERVATION_OR_REAL_MODE_NOT_ENABLED'';end if;\n  if not exists(select 1 from private.policies where version=p_policy and active) or not exists(select 1 from private.catalog_versions where version=p_catalog and active) then raise exception ''STALE_POLICY_OR_CATALOG'';end if;\n  if not exists(select 1 from private.issues where id=p_issue and sample_kind=''SYNTHETIC'') then raise exception ''SYNTHETIC_ISSUE_REQUIRED'';end if;\n  if length(trim(coalesce(b->>''title'',''''))) not between 1 and 200 or length(trim(coalesce(b->>''summary'',''''))) not between 1 and 1500\n    or length(trim(coalesce(b->>''issue_analysis'',''''))) not between 1 and 20000 then raise exception ''CORE_TEXT_REQUIRED'';end if;\n  if coalesce(b->>''article_kind'','''') not in (''SECTOR'',''MACRO'') or coalesce(b->>''source_market'','''') not in (''KR'',''US'',''GLOBAL'',''SYNTHETIC'') or coalesce(b->>''selection_market_basis'','''') not in (''KR'',''FOREIGN_US'') then raise exception ''ARTICLE_MARKET_REQUIRED'';end if;\n  if b ? ''analysis_perspective'' and b->>''analysis_perspective''<>''KR_EQUITY'' then raise exception ''KR_PERSPECTIVE_REQUIRED'';end if;\n  sector:=nullif(b->>''primary_sector_id'','''')::uuid;\n  if b->>''article_kind''=''SECTOR'' and sector is null then raise exception ''PRIMARY_SECTOR_REQUIRED'';end if;\n  if sector is not null and not exists(select 1 from private.sectors where id=sector and active and catalog_version=p_catalog and sample_kind=''SYNTHETIC'') then raise exception ''PRIMARY_SECTOR_INACTIVE'';end if;\n  if jsonb_typeof(b->''key_issues'') is distinct from ''array'' or jsonb_array_length(b->''key_issues'') not between 1 and 12 then raise exception ''KEY_ISSUES_REQUIRED'';end if;\n  for x in select value from jsonb_array_elements(b->''key_issues'') loop if jsonb_typeof(x)<>''string'' or length(trim(x#>>''{}'')) not between 1 and 1000 then raise exception ''INVALID_KEY_ISSUE'';end if;end loop;\n  if jsonb_typeof(b->''sources'') is distinct from ''array'' or jsonb_array_length(b->''sources'') not between 1 and 12 then raise exception ''SOURCES_REQUIRED'';end if;\n  for x in select value from jsonb_array_elements(b->''sources'') loop\n    if length(trim(coalesce(x->>''name'',''''))) not between 1 and 100 or coalesce(x->>''url'','''')!~''^https://[a-z0-9.-]+\\.invalid(/[^[:space:]]*)?$'' or length(x->>''url'')>2048 then raise exception ''SYNTHETIC_SOURCE_REQUIRED'';end if;\n  end loop;\n  if jsonb_typeof(b->''impacts'') is distinct from ''array'' or jsonb_array_length(b->''impacts'') not between 1 and 30 then raise exception ''KR_IMPACT_PATH_REQUIRED'';end if;\n  for x in select value from jsonb_array_elements(b->''impacts'') loop\n    sector:=(x->>''sector_id'')::uuid;path:=x->>''path_id'';direction:=x->>''direction'';cd:=coalesce(x->>''conditional_direction'',''NONE'');\n    if sector is null or not exists(select 1 from private.sectors where id=sector and active and catalog_version=p_catalog and sample_kind=''SYNTHETIC'') then raise exception ''IMPACT_SECTOR_INACTIVE'';end if;\n    if path is null or path!~''^[A-Za-z0-9_-]{1,80}$'' or coalesce(direction,'''') not in (''BENEFIT'',''DAMAGE'',''RELATED'') or cd not in (''NONE'',''POSITIVE'',''NEGATIVE'') or direction<>''RELATED'' and cd<>''NONE'' then raise exception ''INVALID_IMPACT_PATH'';end if;\n    key:=sector::text||'':''||path;if key=any(seen) then raise exception ''DUPLICATE_SECTOR_PATH'';end if;seen:=array_append(seen,key);\n    if length(trim(coalesce(x->>''description'',''''))) not between 1 and 1500 then raise exception ''IMPACT_DESCRIPTION_REQUIRED'';end if;\n    if jsonb_typeof(x->''evidence_ids'') is distinct from ''array'' or jsonb_array_length(x->''evidence_ids'') not between 1 and 10 then raise exception ''PATH_EVIDENCE_REQUIRED'';end if;\n    for e in select value::uuid from jsonb_array_elements_text(x->''evidence_ids'') loop\n      if e is null or not exists(select 1 from private.claims where id=e and issue_id=p_issue and verified and korea_path_verified and fact_current and sample_kind=''SYNTHETIC'' and claim_type<>''SENSITIVE_UNCONFIRMED'' and (valid_until is null or valid_until>now())) then raise exception ''PATH_EVIDENCE_NOT_VERIFIED'';end if;\n    end loop;\n    if jsonb_typeof(coalesce(x->''conditions'',''[]''))<>''array'' or direction=''RELATED'' and cd<>''NONE'' and jsonb_array_length(coalesce(x->''conditions'',''[]''))=0 then raise exception ''PATH_CONDITION_REQUIRED'';end if;\n    if direction=''BENEFIT'' or cd=''POSITIVE'' then positive:=array_append(positive,path);end if;\n    if direction=''DAMAGE'' or cd=''NEGATIVE'' then negative:=array_append(negative,path);end if;\n    if direction=''BENEFIT'' then benefit:=benefit||jsonb_build_array(sector);elsif direction=''DAMAGE'' then damage:=damage||jsonb_build_array(sector);else related:=related||jsonb_build_array(sector);end if;\n    all_sectors:=all_sectors||jsonb_build_array(sector);\n    impacts:=impacts||jsonb_build_array(jsonb_build_object(''sector_id'',sector,''path_id'',path,''direction'',direction,''conditional_direction'',cd,''description'',x->>''description'',''conditions'',coalesce(x->''conditions'',''[]''),''evidence_ids'',x->''evidence_ids''));\n  end loop;\n  if jsonb_array_length(benefit)=0 and jsonb_array_length(damage)=0 then profile:=''RELATED_CONDITIONAL'';\n  elsif cardinality(positive)>0 and cardinality(negative)>0 then profile:=''POSITIVE_NEGATIVE'';\n  elsif cardinality(positive)>0 then profile:=''POSITIVE_ONLY'';else profile:=''DAMAGE_ONLY'';end if;\n  scenarios:=coalesce(b->''scenarios'',''[]'');if jsonb_typeof(scenarios)<>''array'' then raise exception ''INVALID_SCENARIOS'';end if;\n  select count(*) filter(where value->>''direction''=''POSITIVE''),count(*) filter(where value->>''direction''=''NEGATIVE'') into pos_count,neg_count from jsonb_array_elements(scenarios);\n  if cardinality(positive)=0 then\n    if jsonb_array_length(scenarios)<>0 then raise exception ''NO_POSITIVE_PATH_NO_SCENARIOS'';end if;\n  elsif pos_count<>1 or neg_count<>(case when cardinality(negative)>0 then 1 else 0 end) or jsonb_array_length(scenarios)<>pos_count+neg_count then raise exception ''SCENARIO_PATH_MISMATCH'';end if;\n  for x in select value from jsonb_array_elements(scenarios) loop\n    if length(trim(coalesce(x->>''title'',''''))) not between 1 and 200 or length(trim(coalesce(x->>''expected_result'',''''))) not between 1 and 2000 or jsonb_typeof(x->''checks'') is distinct from ''array'' or jsonb_array_length(x->''checks'')=0\n      or jsonb_typeof(x->''path_ids'') is distinct from ''array'' or jsonb_array_length(x->''path_ids'')=0 then raise exception ''SCENARIO_CONTENT_REQUIRED'';end if;\n    for path in select value from jsonb_array_elements_text(x->''path_ids'') loop\n      if path is null or not path=any(case when x->>''direction''=''POSITIVE'' then positive else negative end) then raise exception ''SCENARIO_EVIDENCE_PATH_MISMATCH'';end if;\n    end loop;\n  end loop;\n  if jsonb_typeof(coalesce(b->''risks'',''[]''))<>''array'' then raise exception ''INVALID_RISKS'';end if;\n  if profile=''DAMAGE_ONLY'' and jsonb_array_length(coalesce(b->''risks'',''[]''))=0 then raise exception ''DAMAGE_REQUIRES_RISKS'';end if;\n  if jsonb_typeof(coalesce(b->''schedule'',''[]''))<>''array'' then raise exception ''INVALID_SCHEDULE'';end if;\n  for x in select value from jsonb_array_elements(coalesce(b->''schedule'',''[]'')) loop\n    if coalesce(x->>''status'','''') not in (''VERIFIED'',''CANCELLED'',''UNVERIFIED'',''SUPERSEDED'') then raise exception ''SCHEDULE_STATUS_REQUIRED'';end if;\n    if x->>''status''=''VERIFIED'' then\n      kind:=x->>''kind'';tz:=x->>''timezone'';\n      if coalesce(kind,'''') not in (''EXACT'',''PERIOD'') or not exists(select 1 from pg_catalog.pg_timezone_names where name=tz) or length(trim(coalesce(x->>''title'',''''))) not between 1 and 200 or nullif(x->>''evidence_as_of'','''')::timestamptz is null or (x->>''evidence_as_of'')::timestamptz>now() then raise exception ''SCHEDULE_VERIFICATION_REQUIRED'';end if;\n      if jsonb_typeof(x->''evidence_ids'') is distinct from ''array'' or jsonb_array_length(x->''evidence_ids'')=0 then raise exception ''SCHEDULE_EVIDENCE_REQUIRED'';end if;\n      for e in select value::uuid from jsonb_array_elements_text(x->''evidence_ids'') loop\n        if not exists(select 1 from private.claims where id=e and issue_id=p_issue and verified and fact_current and official_original and (valid_until is null or valid_until>now())) then raise exception ''SCHEDULE_OFFICIAL_EVIDENCE_REQUIRED'';end if;\n      end loop;\n      if kind=''EXACT'' then\n        if nullif(x->>''event_at'','''')::timestamptz is null then raise exception ''SCHEDULE_INSTANT_REQUIRED'';end if;\n      else\n        start_at:=nullif(x->>''period_start'','''')::timestamptz;end_at:=nullif(x->>''period_end'','''')::timestamptz;\n        if start_at is null or end_at is null or start_at>=end_at or length(trim(coalesce(x->>''period_label'',''''))) not between 1 and 100 or length(trim(coalesce(x->>''precision'',''''))) not between 1 and 40 or x ? ''event_at'' then raise exception ''SCHEDULE_PERIOD_REQUIRED'';end if;\n      end if;\n    end if;\n    schedules:=schedules||jsonb_build_array(x);\n  end loop;\n  return jsonb_build_object(''_contract'',''M1'',''_profile'',profile,''_positive_paths'',to_jsonb(positive),''_negative_paths'',to_jsonb(negative),\n    ''title'',b->>''title'',''summary'',b->>''summary'',''article_kind'',b->>''article_kind'',''primary_sector_id'',nullif(b->>''primary_sector_id'','''')::uuid,\n    ''source_market'',b->>''source_market'',''selection_market_basis'',b->>''selection_market_basis'',''analysis_perspective'',''KR_EQUITY'',\n    ''key_issues'',b->''key_issues'',''issue_analysis'',b->>''issue_analysis'',''sources'',b->''sources'',''scenarios'',scenarios,''impacts'',impacts,\n    ''benefit_sector_ids'',benefit,''damage_sector_ids'',damage,''related_sector_ids'',related,''filter_sector_ids'',all_sectors,''risks'',coalesce(b->''risks'',''[]''),''schedule'',schedules);\nend", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "ab50656c7e81b77cb44da5c9ed335201efb452684b14eff62c88fbe68e57304b"}, {"name": "private.m1_prepare_v2", "signature": "uuid,jsonb,bigint,bigint", "body": "\ndeclare b jsonb;k text;items jsonb;\nbegin\n  b:=private.m1_prepare_v1(p_issue,p_input,p_policy,p_catalog);\n  foreach k in array array[''benefit_sector_ids'',''damage_sector_ids'',''related_sector_ids'',''filter_sector_ids''] loop\n    select coalesce(jsonb_agg(value order by value),''[]'') into items from(select distinct value from jsonb_array_elements(b->k)) s;\n    b:=jsonb_set(b,array[k],items);\n  end loop;return b;\nend", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "1546ee2bd084ff95d1824ef5ed3459fa4ad6cc8bd9f99ac5bcd527c6e2326f8a"}, {"name": "private.m1_prepare_v3", "signature": "uuid,jsonb,bigint,bigint", "body": "\ndeclare b jsonb;x jsonb;key text;\nbegin\n  b:=private.m1_prepare_v2(p_issue,p_input,p_policy,p_catalog);\n  if not private.m1_text_array(b->''risks'',20,1500) then raise exception ''INVALID_RISK_TEXT'';end if;\n  for x in select value from jsonb_array_elements(b->''impacts'') loop if not private.m1_text_array(x->''conditions'',10,1000) then raise exception ''INVALID_CONDITION_TEXT'';end if;end loop;\n  for x in select value from jsonb_array_elements(b->''scenarios'') loop\n    if jsonb_typeof(x->''title'') is distinct from ''string'' or jsonb_typeof(x->''expected_result'') is distinct from ''string'' or not private.m1_text_array(x->''checks'',10,1000) then raise exception ''INVALID_SCENARIO_TEXT'';end if;\n  end loop;\n  for x in select value from jsonb_array_elements(b->''schedule'') where value->>''status''=''VERIFIED'' loop\n    foreach key in array (case when x->>''kind''=''EXACT'' then array[''event_at'',''evidence_as_of''] else array[''period_start'',''period_end'',''evidence_as_of''] end) loop\n      if coalesce(x->>key,'''')!~''T[^[:space:]]*(Z|[+-][0-9]{2}:[0-9]{2})$'' then raise exception ''SCHEDULE_OFFSET_REQUIRED'';end if;\n    end loop;\n  end loop;\n  return b;\nend", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "a21e5e5d624af68c3c2a37f93c9425917a13fe127eb8dd30c6fb6df5602c5e7b"}, {"name": "private.m1_prepare_v4", "signature": "uuid,jsonb,bigint,bigint", "body": "\ndeclare b jsonb;\nbegin\n b:=private.m1_prepare_v3(p_issue,p_input,p_policy,p_catalog);\n if b->>''article_kind''=''SECTOR'' and not exists(select 1 from jsonb_array_elements_text(b->''filter_sector_ids'') x where x=b->>''primary_sector_id'') then raise exception ''PRIMARY_SECTOR_PATH_REQUIRED'';end if;\n return b;\nend", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "ffe73c8f6c0a94299efac99b8e9532af2da496283bc8a3707539007967165955"}, {"name": "private.m1_publish_draft_v1", "signature": "uuid,bigint,bigint,bigint,bigint,text", "body": "\ndeclare d private.editor_drafts;b jsonb;result jsonb;i private.issues;request_hash text;prior private.outbox;\nbegin perform private.m1_assert_editor();\n  if p_effect_key is null or length(p_effect_key) not between 1 and 200 then raise exception ''EFFECT_KEY_REQUIRED'';end if;\n  select * into strict i from private.issues where id=p_issue for update;select * into strict d from private.editor_drafts where issue_id=p_issue for update;\n  request_hash:=encode(extensions.digest(convert_to(jsonb_build_object(''issue'',p_issue,''draft_revision'',p_expected_revision,''issue_revision'',p_issue_revision,''policy'',p_policy,''catalog'',p_catalog)::text,''UTF8''),''sha256''),''hex'');\n  select * into prior from private.outbox where effect_key=p_effect_key;\n  if found then\n    if prior.issue_id is distinct from p_issue or prior.payload->>''editor_request_hash'' is distinct from request_hash then raise exception ''EFFECT_PAYLOAD_CONFLICT'';end if;\n    return jsonb_build_object(''status'',''ALREADY_APPLIED'',''issue_id'',i.id,''revision'',i.revision,''version_id'',prior.version_id);\n  end if;\n  if d.revision is distinct from p_expected_revision or i.revision is distinct from p_issue_revision then raise exception ''REVISION_CONFLICT'' using errcode=''40001'';end if;\n  if i.scheduled_publish_at is not null then raise exception ''RESERVATION_NOT_ENABLED'';end if;\n  b:=private.m1_prepare(p_issue,d.content,p_policy,p_catalog);\n  update private.issues set primary_sector_id=nullif(b->>''primary_sector_id'','''')::uuid,manual_protected=true where id=p_issue;\n  result:=private.m0_publish_legacy(p_issue,p_issue_revision,b->>''title'',b->>''summary'',b,b->>''_profile'',p_policy,p_catalog,p_effect_key);\n  -- Replace M0''s synthetic placeholder paths with the verified per-path input.\n  delete from private.impacts where version_id=(result->>''version_id'')::uuid;\n  insert into private.impacts(version_id,sector_id,direction,path_id,conditions,evidence_ids)\n    select (result->>''version_id'')::uuid,(x->>''sector_id'')::uuid,x->>''direction'',x->>''path_id'',x->''conditions'',array(select value::uuid from jsonb_array_elements_text(x->''evidence_ids'')) from jsonb_array_elements(b->''impacts'') x;\n  update private.outbox set payload=payload||jsonb_build_object(''editor_request_hash'',request_hash,''editor_draft_revision'',d.revision) where effect_key=p_effect_key;\n  insert into private.audits(actor_id,action,entity_id) values(auth.uid()::text,''MANUAL_PUBLISH'',p_issue::text);\n  return result;\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "e6b0b87d76e76e7dc93f4a72e772226f0a8fe8fe87c458dc0c05c42a30ea0b6c"}, {"name": "private.m1_save_draft_v1", "signature": "uuid,bigint,jsonb", "body": "\ndeclare d private.editor_drafts;\nbegin perform private.m1_assert_editor();\n  if p_content is null or jsonb_typeof(p_content)<>''object'' or pg_column_size(p_content)>131072 or p_content ? ''scheduled_publish_at'' then raise exception ''INVALID_DRAFT_OR_RESERVATION'';end if;\n  select * into strict d from private.editor_drafts where issue_id=p_issue for update;\n  if d.revision is distinct from p_expected_revision then raise exception ''REVISION_CONFLICT'' using errcode=''40001'';end if;\n  update private.editor_drafts set content=p_content,revision=revision+1,updated_at=now(),updated_by=auth.uid() where issue_id=p_issue;\n  update private.issues set manual_protected=true where id=p_issue;\n  insert into private.audits(actor_id,action,entity_id) values(auth.uid()::text,''MANUAL_DRAFT_SAVE'',p_issue::text);\n  return jsonb_build_object(''draft_revision'',d.revision+1);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "fad16f2d4453cf08bbc0f44354d490830c2ec4a9deca06ee9cd9d46c34dd5776"}, {"name": "private.m1_schedule", "signature": "jsonb,timestamptz", "body": "\n  select coalesce(jsonb_agg(case when x->>''kind''=''EXACT'' then jsonb_build_object(''kind'',''EXACT'',''title'',x->>''title'',''event_at'',x->>''event_at'',''timezone'',x->>''timezone'')\n    else jsonb_build_object(''kind'',''PERIOD'',''title'',x->>''title'',''period_label'',x->>''period_label'',''date_note'',''정확한 날짜 미정'',''timezone'',x->>''timezone'') end),''[]'')\n  from jsonb_array_elements(coalesce(p_items,''[]'')) x\n  where x->>''status''=''VERIFIED'' and case when x->>''kind''=''EXACT'' then (x->>''event_at'')::timestamptz>p_now when x->>''kind''=''PERIOD'' then (x->>''period_end'')::timestamptz>p_now else false end\n", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "bac33907136476ac716bd58d5c18e40a520f344bfb15045fd9f5e93b013c6d52"}, {"name": "private.m1_text_array", "signature": "jsonb,int,int", "body": "\n select case when jsonb_typeof(p_value) is distinct from ''array'' then false else jsonb_array_length(p_value)<=p_max and not exists(select 1 from jsonb_array_elements(p_value) x where jsonb_typeof(x)<>''string'' or length(trim(x#>>''{}'')) not between 1 and p_length) end\n", "securityDefiner": false, "volatility": "i", "config": ["search_path=\"\""], "definitionSha256": "30ce0b807c0a6b6289c8136d90427e32222d51593954dbbd2c58a7b9913aecb0"}, {"name": "private.public_body", "signature": "jsonb,text[],timestamptz", "body": "\ndeclare r jsonb;impact jsonb;items jsonb:=''[]'';name text;\nbegin\n if p_body->>''_contract'' is distinct from ''M1'' then return private.m0_public_body(p_body,p_sections,p_now);end if;\n r:=jsonb_build_object(''key_issues'',p_body->''key_issues'',''issue_analysis'',p_body->>''issue_analysis'',\n ''sources'',(select coalesce(jsonb_agg(jsonb_build_object(''name'',x->>''name'',''url'',x->>''url'')),''[]'') from jsonb_array_elements(p_body->''sources'') x),\n ''visible_sections'',p_sections,''source_market'',p_body->>''source_market'',''selection_market_basis'',p_body->>''selection_market_basis'',''analysis_perspective'',''KR_EQUITY'',''impact_profile'',p_body->>''_profile'',''article_kind'',p_body->>''article_kind'');\n for impact in select value from jsonb_array_elements(p_body->''impacts'') loop\n  select s.name into name from private.sectors s where s.id=(impact->>''sector_id'')::uuid and s.active;\n  if found then items:=items||jsonb_build_array(jsonb_build_object(''sector_id'',impact->>''sector_id'',''sector_name'',name,''path_id'',impact->>''path_id'',''direction'',impact->>''direction'',''conditional_direction'',impact->>''conditional_direction'',''description'',impact->>''description'',''conditions'',impact->''conditions''));end if;\n end loop;\n r:=r||jsonb_build_object(''impacts'',items);\n if ''SCENARIOS''=any(p_sections) then r:=r||jsonb_build_object(''scenarios'',(select jsonb_agg(jsonb_build_object(''direction'',x->>''direction'',''title'',x->>''title'',''expected_result'',x->>''expected_result'',''checks'',x->''checks'',''path_ids'',x->''path_ids'')) from jsonb_array_elements(p_body->''scenarios'') x));end if;\n if ''RISKS''=any(p_sections) then r:=r||jsonb_build_object(''risks'',p_body->''risks'');end if;\n if ''SCHEDULE''=any(p_sections) then r:=r||jsonb_build_object(''schedule'',private.m1_live_schedule(p_body,p_now));end if;\n return r;\nend", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "30c0b04c99238be4fa72c00e7dd802665a827e99a12d9352a831d503d2708ffd"}, {"name": "private.sync_public_issue", "signature": "", "body": "\ndeclare v private.article_versions;\nbegin\n  if new.publication_state=''PUBLISHED'' and new.current_version_id is not null then\n    select * into strict v from private.article_versions where id=new.current_version_id and issue_id=new.id;\n    insert into public.news_public(issue_id,version_id,publication_state,title,summary,body,first_published_at,material_change_at,sample_kind)\n    values(new.id,v.id,new.publication_state,v.title,v.summary,private.public_body(v.public_body,v.visible_sections,now()),new.first_published_at,new.material_change_at,new.sample_kind)\n    on conflict(issue_id) do update set version_id=excluded.version_id,publication_state=excluded.publication_state,title=excluded.title,summary=excluded.summary,body=excluded.body,first_published_at=excluded.first_published_at,material_change_at=excluded.material_change_at;\n  else\n    update public.news_public set publication_state=new.publication_state,title=null,summary=null,body=null where issue_id=new.id;\n  end if;\n  return new;\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "94e5b2482623e45d05416bd64139bae2ce47271380b08ecef137126c87afd406"}, {"name": "private.visible_sections", "signature": "text,jsonb,timestamptz,timestamptz", "body": "\ndeclare r text[]:=array[''KEY_ISSUES'',''ISSUE_ANALYSIS''];\nbegin\n if p_body->>''_contract'' is distinct from ''M1'' then return private.m0_visible_sections(p_profile,p_body,p_as_of,p_now);end if;\n if p_profile is distinct from p_body->>''_profile'' then raise exception ''SCENARIO_PATH_MISMATCH'';end if;\n if jsonb_array_length(p_body->''_positive_paths'')>0 then r:=array_append(r,''SCENARIOS'');end if;\n if jsonb_array_length(p_body->''benefit_sector_ids'')>0 then r:=array_append(r,''BENEFIT_SECTORS'');end if;\n if jsonb_array_length(p_body->''damage_sector_ids'')>0 then r:=array_append(r,''DAMAGE_SECTORS'');end if;\n if jsonb_array_length(p_body->''related_sector_ids'')>0 then r:=array_append(r,''RELATED_SECTORS'');end if;\n if jsonb_array_length(p_body->''risks'')>0 then r:=array_append(r,''RISKS'');end if;\n if jsonb_array_length(private.m1_live_schedule(p_body,greatest(p_as_of,p_now)))>0 then r:=array_append(r,''SCHEDULE'');end if;\n return array_append(r,''SOURCES'');\nend", "securityDefiner": false, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "d6a7a168e37bfb4038480980aae6df9aee7b60eda6b2fc1b480f376197799f0b"}, {"name": "public.get_public_article", "signature": "uuid", "body": "\ndeclare r jsonb;canonical uuid;\nbegin\n r:=public.resolve_issue(p_issue);if r->>''state''<>''PUBLISHED'' then return r;end if;canonical:=(r->>''canonical_issue_id'')::uuid;\n if exists(select 1 from private.issues i join private.article_versions v on v.id=i.current_version_id where i.id=canonical and v.public_body->>''_contract''=''M1'') and not private.m1_current_evidence(canonical) then return jsonb_build_object(''state'',''CORRECTION_PENDING'',''message'',''근거·분류 재확인 중 · 기존 내용 제공 중지'');end if;\n return private.m0_get_public_article_legacy(p_issue);\nend", "securityDefiner": true, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "6627fe79793fd45007b0306d0a51bad02df306217023c8c803270863b6070afd"}, {"name": "public.is_news_visible", "signature": "uuid", "body": "\n select exists(select 1 from private.issues i join private.article_versions v on v.id=i.current_version_id where i.id=p_issue and i.publication_state=''PUBLISHED''\n   and (v.public_body->>''_contract'' is distinct from ''M1'' or private.m1_current_evidence(i.id)))\n", "securityDefiner": true, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "8513447a8da0a956253f9cd2720c8e788be8a85054a17761cbd417b21ddd5324"}, {"name": "public.m0_ack", "signature": "uuid,uuid,text", "body": "\ndeclare j private.jobs;previous text;\nbegin\n  perform private.assert_server();perform private.assert_initialized();\n  if p_receipt is null or length(p_receipt) not between 1 and 300 then raise exception ''RECEIPT_REQUIRED'';end if;\n  select * into strict j from private.jobs where id=p_job for update;\n  if j.state=''SUCCEEDED'' and j.lease_token=p_token and exists(select 1 from private.effect_receipts where effect_key=j.effect_key and external_receipt=p_receipt) then return jsonb_build_object(''status'',''ALREADY_APPLIED'');end if;\n  if j.state<>''LEASED'' or j.lease_token is distinct from p_token or j.lease_until<=clock_timestamp() then raise exception ''STALE_LEASE'' using errcode=''40001'';end if;\n  if not exists(select 1 from private.job_attempts where job_id=j.id and lease_token=p_token and effect_state=''DISPATCH_INTENT'') then raise exception ''EFFECT_INTENT_REQUIRED'';end if;\n  select external_receipt into previous from private.effect_receipts where effect_key=j.effect_key;\n  if previous is not null and previous<>p_receipt then raise exception ''RECEIPT_CONFLICT'';end if;\n  insert into private.effect_receipts(effect_key,external_receipt) values(j.effect_key,p_receipt) on conflict(effect_key) do nothing;\n  update private.jobs set state=''SUCCEEDED'',completed_at=clock_timestamp(),lease_until=null where id=j.id;\n  update private.job_attempts set ended_at=clock_timestamp(),result=''SUCCEEDED'',effect_state=''ACCEPTED'' where job_id=j.id and lease_token=p_token;\n  return jsonb_build_object(''status'',''APPLIED'');\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "8f2461b447c2943b168598efd0cc5c283b3bf116e6de01e768c1dbe082dc1bff"}, {"name": "public.m0_admin_view_count", "signature": "uuid", "body": "\nbegin perform private.assert_editor();perform private.assert_initialized();return(select count(*) from private.view_events where issue_id=p_issue);end", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "2f7e8292e3eddd27d91c3b22a90d7cead8378396fca815fee94d7fc5a31ce3d9"}, {"name": "public.m0_claim", "signature": "text,int", "body": "\ndeclare j private.jobs;token uuid:=gen_random_uuid();\nbegin\n  perform private.assert_server();perform private.assert_initialized();\n  if p_owner is null or length(p_owner) not between 1 and 80 or p_lease_seconds not between 1 and 120 then raise exception ''INVALID_LEASE'';end if;\n  select * into j from private.jobs where available_at<=clock_timestamp() and (state=''QUEUED'' or state=''LEASED'' and lease_until<=clock_timestamp()) order by available_at,created_at for update skip locked limit 1;\n  if not found then return null;end if;\n  if j.state=''LEASED'' then update private.job_attempts set ended_at=clock_timestamp(),result=''LEASE_EXPIRED'' where job_id=j.id and lease_token=j.lease_token and ended_at is null;end if;\n  if j.state=''LEASED'' and exists(select 1 from private.job_attempts where job_id=j.id and lease_token=j.lease_token and effect_state in (''DISPATCH_INTENT'',''UNCERTAIN'')) then\n    update private.jobs set state=''WAIT_CONFIRMATION'',lease_token=null,lease_until=null,last_error_code=''LEASE_EXPIRED_UNCERTAIN'' where id=j.id;return null;\n  end if;\n  if j.attempts>=j.max_attempts then update private.jobs set state=''DLQ'',lease_token=null,lease_until=null,last_error_code=''MAX_ATTEMPTS'' where id=j.id;return null;end if;\n  update private.jobs set state=''LEASED'',lease_token=token,lease_owner=p_owner,lease_until=clock_timestamp()+p_lease_seconds*interval ''1 second'',attempts=attempts+1 where id=j.id returning * into j;\n  insert into private.job_attempts(job_id,lease_token,attempt) values(j.id,token,j.attempts);\n  return jsonb_build_object(''id'',j.id,''environment'',j.environment,''job_schema_version'',j.job_schema_version,''kind'',j.kind,''effect_key'',j.effect_key,''payload'',j.payload,''lease_token'',token,''lease_until'',j.lease_until,''attempt'',j.attempts);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "e3bd2e8f2d8a928a1a09b7f03d16bf6c46f7b42f6202a8cf69e56a5c3afff061"}, {"name": "public.m0_create_installation", "signature": "", "body": "\ndeclare i uuid:=gen_random_uuid();secret text:=encode(extensions.gen_random_bytes(32),''hex'');\nbegin\n  perform private.assert_server();perform private.assert_initialized();\n  insert into private.installations(id,secret_hash,expires_at) values(i,extensions.digest(convert_to(secret,''UTF8''),''sha256''),clock_timestamp()+interval ''1 day'');\n  insert into private.installation_settings(installation_id) values(i);\n  return jsonb_build_object(''installation_id'',i,''secret'',secret,''secret_version'',1,''sample_kind'',''SYNTHETIC'',''notice'',''Server-only local capability fixture; never log this response'');\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "7da2a30c2f2a2c52dab8ccb339eb0c38d262ff215de388890af0d1840264b99f"}, {"name": "public.m0_enqueue", "signature": "text,jsonb,text,int,text", "body": "\ndeclare j private.jobs;\nbegin\n  perform private.assert_server();perform private.assert_initialized();\n  if p_environment<>''preview'' or p_schema_version<>1 or p_kind<>''MOCK_EFFECT'' then raise exception ''UNSUPPORTED_JOB_CONTRACT'';end if;\n  if p_effect_key is null or length(p_effect_key) not between 1 and 200 or jsonb_typeof(p_payload)<>''object'' then raise exception ''INVALID_JOB'';end if;\n  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in (''fixture_run_id'',''mode'',''work_ms'',''heartbeat'')) then raise exception ''UNSUPPORTED_JOB_PAYLOAD'';end if;\n  insert into private.jobs(environment,job_schema_version,kind,effect_key,payload) values(p_environment,p_schema_version,p_kind,p_effect_key,p_payload) on conflict(effect_key) do nothing;\n  select * into strict j from private.jobs where effect_key=p_effect_key;\n  if j.payload<>p_payload or j.environment<>p_environment or j.kind<>p_kind or j.job_schema_version<>p_schema_version then raise exception ''EFFECT_PAYLOAD_CONFLICT'';end if;\n  return jsonb_build_object(''id'',j.id,''effect_key'',j.effect_key,''state'',j.state);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "55912b706ac7880f754131ea71b78c39dda2236edb3cb032c8861052e96235ae"}, {"name": "public.m0_enqueue_due", "signature": "", "body": "\ndeclare s private.schedules;j jsonb;n integer:=0;\nbegin\n  perform private.assert_server();perform private.assert_initialized();\n  for s in select * from private.schedules where enabled and due_at<=clock_timestamp() and enqueued_job_id is null for update skip locked loop\n    j:=public.m0_enqueue(s.effect_key,jsonb_build_object(''fixture_run_id'',s.fixture_run_id,''mode'',''NORMAL''));\n    update private.schedules set enqueued_job_id=(j->>''id'')::uuid where id=s.id;n:=n+1;\n  end loop;return n;\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "f13562127944a48eed23784dc2438f7e49c12d47fa53d20f78b9811c853e040d"}, {"name": "public.m0_fail", "signature": "uuid,uuid,boolean,text", "body": "\ndeclare j private.jobs;next_state private.job_state;\nbegin\n  perform private.assert_server();perform private.assert_initialized();\n  if p_uncertain is null then raise exception ''UNCERTAINTY_REQUIRED'';end if;\n  if p_error_code is null or length(p_error_code) not between 1 and 100 then raise exception ''ERROR_CODE_REQUIRED'';end if;\n  select * into strict j from private.jobs where id=p_job for update;\n  if j.state<>''LEASED'' or j.lease_token is distinct from p_token or j.lease_until<=clock_timestamp() then raise exception ''STALE_LEASE'' using errcode=''40001'';end if;\n  next_state:=case when p_uncertain then ''WAIT_CONFIRMATION''::private.job_state when j.attempts>=j.max_attempts then ''DLQ''::private.job_state else ''QUEUED''::private.job_state end;\n  update private.jobs set state=next_state,available_at=clock_timestamp()+least(60,power(2,j.attempts)) * interval ''1 second'',lease_token=null,lease_until=null,last_error_code=p_error_code where id=j.id;\n  update private.job_attempts set ended_at=clock_timestamp(),result=next_state::text,effect_state=case when p_uncertain then ''UNCERTAIN'' else ''NOT_SENT_CONFIRMED'' end where job_id=j.id and lease_token=p_token;\n  return jsonb_build_object(''state'',next_state,''effect_key'',j.effect_key);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "4f17e9114a99c695367369e585051984d8d71e6de663359f35e6360955d321da"}, {"name": "public.m0_get_settings", "signature": "uuid,text,int", "body": "\ndeclare s private.installation_settings;\nbegin\n  perform private.assert_server();perform private.assert_initialized();perform private.assert_installation(p_install,p_secret,p_version);\n  select * into strict s from private.installation_settings where installation_id=p_install;\n  return jsonb_build_object(''morning_issue'',s.morning_issue,''closing_issue'',s.closing_issue,''favorite_sector_issue'',s.favorite_sector_issue,''sector_ids'',s.sector_ids);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "5935d1be508f1fc1806328c1cc1fb6ab4566b4df84265fc6192d960c94a71d00"}, {"name": "public.m0_heartbeat", "signature": "uuid,uuid,int", "body": "\ndeclare updated integer;\nbegin\n  perform private.assert_server();perform private.assert_initialized();if p_lease_seconds not between 1 and 120 then raise exception ''INVALID_LEASE'';end if;\n  update private.jobs set lease_until=clock_timestamp()+p_lease_seconds*interval ''1 second'' where id=p_job and state=''LEASED'' and lease_token=p_token and lease_until>clock_timestamp();get diagnostics updated=row_count;return updated=1;\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "f9bc9c8f103c3ef5ed523ccd9faa73ae964a3d899b6c364a4150573c3833eedf"}, {"name": "public.m0_job_status", "signature": "uuid", "body": "\ndeclare j private.jobs;\nbegin perform private.assert_server();select * into strict j from private.jobs where id=p_job;\n  return jsonb_build_object(''id'',j.id,''effect_key'',j.effect_key,''state'',j.state,''attempts'',j.attempts,''max_attempts'',j.max_attempts,''lease_until'',j.lease_until,''last_error_code'',j.last_error_code,''receipt'',(select external_receipt from private.effect_receipts where effect_key=j.effect_key));\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "930fd77496518e22729473aed116eda174a0e59be6d7dfa7ec8ec15311263d39"}, {"name": "public.m0_mark_effect_intent", "signature": "uuid,uuid", "body": "\ndeclare j private.jobs;\nbegin\n  perform private.assert_server();perform private.assert_initialized();\n  select * into strict j from private.jobs where id=p_job for update;\n  if j.state<>''LEASED'' or j.lease_token is distinct from p_token or j.lease_until<=clock_timestamp() then return false;end if;\n  update private.job_attempts set effect_state=''DISPATCH_INTENT'' where job_id=j.id and lease_token=p_token and effect_state=''NOT_STARTED'';\n  return found;\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "57b14f4a46dc2a53a5908f4b78781542847a445e998e7ff3037ab08e6b403624"}, {"name": "public.m0_pending_confirmation", "signature": "", "body": "\ndeclare j private.jobs;\nbegin\n  perform private.assert_server();perform private.assert_initialized();\n  select * into j from private.jobs where state=''WAIT_CONFIRMATION'' and confirmation_next_at<=clock_timestamp() order by confirmation_next_at,created_at for update skip locked limit 1;\n  if not found then return null;end if;\n  -- Reserve a bounded confirmation slot before I/O. UNKNOWN stays on hold but\n  -- cannot monopolize every consumer''s next lookup. This never authorizes POST.\n  update private.jobs set confirmation_next_at=clock_timestamp()+interval ''30 seconds'',confirmation_checks=confirmation_checks+1 where id=j.id;\n  return jsonb_build_object(''id'',j.id,''effect_key'',j.effect_key,''payload'',j.payload);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "d32d96b294e29d823e655b1eb234003461a028c6109ba098324b14c93ff62fb7"}, {"name": "public.m0_publish", "signature": "uuid,bigint,text,text,jsonb,text,bigint,bigint,text", "body": "\nbegin perform private.assert_editor();if private.caller_role()=''authenticated'' then raise exception ''M1_EDITOR_RPC_REQUIRED'' using errcode=''42501'';end if;\nreturn private.m0_publish_legacy(p_issue,p_expected_revision,p_title,p_summary,p_body,p_profile,p_policy,p_catalog,p_effect_key);end", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "18f89c80a98e5f2db1fdb478a685ba886d5299f491d20b994e761089cdfa1ea4"}, {"name": "public.m0_reconcile", "signature": "uuid,text,text", "body": "\ndeclare j private.jobs;\nbegin\n  perform private.assert_editor();perform private.assert_initialized();\n  if p_outcome is null or p_outcome not in (''ACCEPTED'',''CONFIRMED_NOT_SENT'') or p_proof is null or length(p_proof) not between 1 and 300 then raise exception ''TERMINAL_PROVIDER_PROOF_REQUIRED'';end if;\n  select * into strict j from private.jobs where id=p_job for update;\n  if j.state<>''WAIT_CONFIRMATION'' then raise exception ''NOT_AWAITING_CONFIRMATION'';end if;\n  if p_outcome=''ACCEPTED'' then\n    insert into private.effect_receipts(effect_key,external_receipt) values(j.effect_key,p_proof) on conflict(effect_key) do nothing;\n    update private.jobs set state=''SUCCEEDED'',completed_at=clock_timestamp() where id=j.id;\n    update private.job_attempts set effect_state=''ACCEPTED'' where job_id=j.id and effect_state in (''DISPATCH_INTENT'',''UNCERTAIN'');\n  else\n    if exists(select 1 from private.effect_receipts where effect_key=j.effect_key) then raise exception ''EFFECT_ALREADY_ACCEPTED'';end if;\n    update private.job_attempts set effect_state=''NOT_SENT_CONFIRMED'' where job_id=j.id and effect_state in (''DISPATCH_INTENT'',''UNCERTAIN'');\n    update private.jobs set state=case when attempts>=max_attempts then ''DLQ''::private.job_state else ''QUEUED''::private.job_state end,available_at=clock_timestamp() where id=j.id;\n  end if;\n  insert into private.audits(actor_id,action,entity_id,details) values(private.caller_role(),''RECONCILE'',j.id::text,jsonb_build_object(''outcome'',p_outcome,''proof'',p_proof,''original_effect_key'',j.effect_key));\n  return jsonb_build_object(''effect_key'',j.effect_key,''outcome'',p_outcome);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "c7477b0d4e69509ccf6b95071b87a21b45abd7934f69a5efe4a78530a2919dad"}, {"name": "public.m0_record_view", "signature": "uuid,text,int,uuid,text", "body": "\ndeclare r jsonb;event_id uuid;\nbegin\n  perform private.assert_server();perform private.assert_initialized();perform private.assert_installation(p_install,p_secret,p_version);\n  if p_event_key is null or length(p_event_key) not between 1 and 100 then raise exception ''EVENT_KEY_REQUIRED'';end if;\n  r:=public.resolve_issue(p_issue);if r->>''state''<>''PUBLISHED'' then raise exception ''ARTICLE_NOT_PUBLIC'';end if;\n  insert into private.view_events(installation_id,issue_id,event_key) values(p_install,(r->>''canonical_issue_id'')::uuid,p_event_key) on conflict(installation_id,event_key) do nothing returning id into event_id;\n  return jsonb_build_object(''recorded'',event_id is not null);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "ee7f49ae3f225e3aa61c06ee0d9ad7cb5fa3449b90129744e7149114ad380106"}, {"name": "public.m0_requeue_dlq", "signature": "uuid,text", "body": "\ndeclare j private.jobs;\nbegin\n  perform private.assert_editor();perform private.assert_initialized();if p_reason is null or length(p_reason) not between 3 and 200 then raise exception ''REPLAY_REASON_REQUIRED'';end if;\n  select * into strict j from private.jobs where id=p_job for update;\n  if j.state<>''DLQ'' or j.attempts>=10 or exists(select 1 from private.effect_receipts where effect_key=j.effect_key) or exists(select 1 from private.job_attempts where job_id=j.id and effect_state in (''DISPATCH_INTENT'',''UNCERTAIN'')) then raise exception ''REPLAY_NOT_ALLOWED'';end if;\n  update private.jobs set state=''QUEUED'',available_at=clock_timestamp(),max_attempts=attempts+1 where id=j.id;\n  insert into private.audits(actor_id,action,entity_id,details) values(private.caller_role(),''DLQ_REPLAY'',j.id::text,jsonb_build_object(''reason'',p_reason,''original_effect_key'',j.effect_key));\n  return jsonb_build_object(''effect_key'',j.effect_key,''max_attempts'',j.attempts+1);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "462fbc4cd11806a55feee9d7df129fc3450078e1db192bd48ca158d7d5b876cc"}, {"name": "public.m0_rotate_installation", "signature": "uuid,text,int", "body": "\ndeclare secret text:=encode(extensions.gen_random_bytes(32),''hex'');\nbegin\n  perform private.assert_server();perform private.assert_initialized();perform private.assert_installation(p_install,p_secret,p_version);\n  update private.installations set secret_hash=extensions.digest(convert_to(secret,''UTF8''),''sha256''),secret_version=secret_version+1,expires_at=clock_timestamp()+interval ''1 day'' where id=p_install and secret_version=p_version;\n  if not found then raise exception ''INSTALLATION_UNAUTHORIZED'' using errcode=''42501'';end if;\n  return jsonb_build_object(''installation_id'',p_install,''secret'',secret,''secret_version'',p_version+1);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "d91fe60493040ffc68a05bba4921112a73618425cc48dca22a56534c1bd93afd"}, {"name": "public.m0_runtime_identity", "signature": "", "body": "\ndeclare r private.runtime_identity;\nbegin perform private.assert_server();select * into r from private.runtime_identity where singleton;\n  return jsonb_build_object(''productId'',r.product_id,''environment'',r.environment,''bootstrapId'',r.bootstrap_id,''schemaVersion'',r.schema_version);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "79128c6e6225ee4a503bf76812e979122218572df08984a750a7e8f7159ccc7a"}, {"name": "public.m0_set_publication_state", "signature": "uuid,bigint,text", "body": "\ndeclare i private.issues;\nbegin\n  perform private.assert_editor();perform private.assert_initialized();\n  if p_state not in (''CORRECTION_PENDING'',''WITHDRAWN'',''HIDDEN'') then raise exception ''INVALID_TRANSITION'';end if;\n  select * into strict i from private.issues where id=p_issue for update;\n  if i.revision is distinct from p_expected_revision then raise exception ''REVISION_CONFLICT'' using errcode=''40001'';end if;\n  update private.issues set publication_state=p_state::private.publication_state,revision=revision+1 where id=i.id;\n  return jsonb_build_object(''issue_id'',i.id,''state'',p_state,''revision'',i.revision+1);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "625af240ac2dedc82dde7594f5486056fe98f4b36175aa62ed2b5d3c997096f7"}, {"name": "public.m0_source_technical_result", "signature": "text,text,text,jsonb", "body": "\ndeclare e private.endpoints;source private.sources;permission private.permission_profiles;k text;\nbegin\n  perform private.assert_server();perform private.assert_initialized();\n  select * into strict e from private.endpoints where id=p_endpoint for update;\n  select * into strict source from private.sources where id=e.source_id;\n  if source.sample_kind<>''SYNTHETIC'' then raise exception ''REAL_SOURCE_TRANSITIONS_NOT_ENABLED_STAGE_4'';end if;\n  if e.status<>''TECH_TEST'' or e.permission_version is distinct from p_permission_version or p_adapter_version is null or e.adapter_id is null or e.adapter_version is distinct from p_adapter_version or not exists(select 1 from private.adapters where id=e.adapter_id and version=e.adapter_version and verification_state=''PASSED'') then raise exception ''TECH_TEST_VERSION_CONFLICT'';end if;\n  select * into strict permission from private.permission_profiles where id=e.permission_profile_id and version=e.permission_version;\n  if permission.status<>''VERIFIED'' or permission.verified_at is null or permission.verified_at>clock_timestamp() or jsonb_array_length(permission.evidence)=0 or permission.expires_at is null or permission.expires_at<=clock_timestamp() or permission.revoked_at is not null or permission.purposes->>''MACHINE_ACCESS'' is distinct from ''ALLOW'' or permission.purposes->>''DISCOVERY'' is distinct from ''ALLOW'' then raise exception ''PERMISSION_NOT_VERIFIED'';end if;\n  foreach k in array array[''listing'',''detail'',''id'',''time'',''pagination'',''failure_handling''] loop\n    if p_checks->k is distinct from ''true''::jsonb then raise exception ''TECH_CHECK_INCOMPLETE'';end if;\n  end loop;\n  update private.endpoints set status=''SHADOW'',health_state=''SHADOW_TESTING'',episode_id=gen_random_uuid(),fast_retry_count=0,reprobe_count=0,low_frequency_since=null where id=e.id;\n  return jsonb_build_object(''state'',''SHADOW'',''action'',''TECH_TEST_VERIFIED_ENTER_SHADOW'',''live_enabled'',false);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "ed032091fb626d375f26e9ac4329daf9df98ea3650ee5679724dca4fe3062d2e"}, {"name": "public.m0_update_settings", "signature": "uuid,text,int,boolean,boolean,boolean,uuid[]", "body": "\nbegin\n  perform private.assert_server();perform private.assert_initialized();perform private.assert_installation(p_install,p_secret,p_version);\n  if p_morning is null or p_closing is null or p_favorite is null or p_sector_ids is null then raise exception ''SETTINGS_REQUIRED'';end if;\n  if cardinality(p_sector_ids)<>(select count(distinct u.sector_id) from unnest(p_sector_ids) as u(sector_id)) then raise exception ''DUPLICATE_OR_NULL_SECTOR'';end if;\n  if exists(select 1 from unnest(p_sector_ids) as u(sector_id) where not exists(select 1 from private.sectors as s where s.id=u.sector_id and s.active)) then raise exception ''INACTIVE_SECTOR'';end if;\n  update private.installation_settings set morning_issue=p_morning,closing_issue=p_closing,favorite_sector_issue=p_favorite,sector_ids=p_sector_ids,updated_at=clock_timestamp() where installation_id=p_install;\n  return public.m0_get_settings(p_install,p_secret,p_version);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "9d075f0dc9bb99b4101f7a49f79e7e1c621598660c75377b8026ec0de993e32a"}, {"name": "public.m1_check_editor", "signature": "", "body": "\nbegin perform private.assert_initialized();if not private.is_admin() then raise exception ''EDITOR_ONLY'' using errcode=''42501'';end if;\nreturn jsonb_build_object(''admin'',true,''sample_kind'',''SYNTHETIC'');end", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "7c62250dedaa92c0798cdf751d96196f5c15046b0001458ac93d4526e513cf58"}, {"name": "public.m1_close_admin_session", "signature": "text", "body": "\ndeclare s private.admin_sessions;\nbegin\n  perform private.assert_server();perform private.assert_initialized();\n  update private.admin_sessions set revoked_at=coalesce(revoked_at,now()) where capability_hash=p_hash returning * into s;\n  if found then insert into private.audits(actor_id,action,entity_id) values(s.user_id::text,''ADMIN_SESSION_CLOSE'',s.auth_session_id::text);end if;\n  return jsonb_build_object(''closed'',true);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "63d5d0f76dda9010adbb58a8f8e9a2e9942bd001092bf6d79e4d110d9fa84ef8"}, {"name": "public.m1_create_draft", "signature": "uuid", "body": "\ndeclare story uuid;issue uuid;claim uuid;content jsonb;\nbegin perform private.m1_assert_editor();if p_request is null then raise exception ''REQUEST_ID_REQUIRED'';end if;\n  insert into private.stories(event_key) values(''M1:''||p_request::text) on conflict(event_key) do nothing;\n  select id into strict story from private.stories where event_key=''M1:''||p_request::text for update;\n  select id into issue from private.issues where story_id=story and angle_key=''MANUAL'';\n  if issue is null then\n    insert into private.issues(story_id,angle_key,sample_kind,manual_protected) values(story,''MANUAL'',''SYNTHETIC'',true) returning id into issue;\n    insert into private.claims(issue_id,claim_type,korea_path_verified,fact_current,official_original,verified,sample_kind) values(issue,''ORDINARY_FACT'',true,true,true,true,''SYNTHETIC'') returning id into claim;\n    content:=jsonb_build_object(''title'','''',''summary'','''',''article_kind'',''SECTOR'',''primary_sector_id'',null,''source_market'',''US'',''selection_market_basis'',''FOREIGN_US'',''analysis_perspective'',''KR_EQUITY'',''key_issues'',''[]''::jsonb,''issue_analysis'','''',''sources'',jsonb_build_array(jsonb_build_object(''name'',''SYNTHETIC 검증 근거'',''url'',''https://example.invalid/manual'')),''impacts'',''[]''::jsonb,''scenarios'',''[]''::jsonb,''risks'',''[]''::jsonb,''schedule'',''[]''::jsonb);\n    insert into private.editor_drafts(issue_id,content,updated_by) values(issue,content,auth.uid());\n  end if;\n  return jsonb_build_object(''issue_id'',issue);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "806dcee0168bccb506b60cf47b60018b33749536d02d9e6bba8092d37c8d864f"}, {"name": "public.m1_dispatch_outbox", "signature": "int", "body": "\ndeclare o private.outbox;r jsonb;result jsonb:=''[]'';\nbegin perform private.assert_server();perform private.assert_initialized();\n  if p_limit is null or p_limit not between 1 and 100 then raise exception ''INVALID_DISPATCH_SIZE'';end if;\n  for o in select * from private.outbox where dispatched_job_id is null and payload ? ''editor_request_hash'' order by created_at,id for update skip locked limit p_limit loop\n    r:=public.m0_enqueue(o.effect_key,jsonb_build_object(''fixture_run_id'',o.id,''mode'',''NORMAL''),''preview'',1,''MOCK_EFFECT'');\n    update private.outbox set dispatched_job_id=(r->>''id'')::uuid where id=o.id;\n    result:=result||jsonb_build_array(jsonb_build_object(''outbox_id'',o.id,''job_id'',r->>''id''));\n  end loop;return result;\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "ca922b1d3df3f0b824041a242b39e7d2976b62508e76045352ed95ea261fd476"}, {"name": "public.m1_editor_articles", "signature": "", "body": "\nbegin perform private.m1_assert_editor();return coalesce((select jsonb_agg(row_to_json(t)) from(select i.id,i.publication_state,i.revision,d.revision draft_revision,d.content->>''title'' title,d.updated_at from private.issues i join private.editor_drafts d on d.issue_id=i.id order by d.updated_at desc limit 100)t),''[]'');end", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "f4887e9031a427b8c5927c29ea441917dcb1e30f85bf77647b9eeaaf5a7e865c"}, {"name": "public.m1_editor_catalog", "signature": "", "body": "\nbegin perform private.m1_assert_editor();return coalesce((select jsonb_agg(jsonb_build_object(''id'',id,''name'',name,''description'',description) order by display_order,id) from private.sectors where active and sample_kind=''SYNTHETIC'' and name not like ''SYNTHETIC M0%''),''[]'');end", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "78a97f52af41b7162a3750f20f805a11c0c35f3b06204f5ef7908f3e257244e8"}, {"name": "public.m1_get_draft", "signature": "uuid", "body": "\nbegin perform private.m1_assert_editor();return(select jsonb_build_object(''issue_id'',i.id,''issue_revision'',i.revision,''state'',i.publication_state,''draft_revision'',d.revision,''content'',d.content,''claim_id'',(select c.id from private.claims c where c.issue_id=i.id order by c.id limit 1),''policy_version'',(select version from private.policies where active),''catalog_version'',(select version from private.catalog_versions where active)) from private.issues i join private.editor_drafts d on d.issue_id=i.id where i.id=p_issue);end", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "a512fbb334d6cca91c78cd94c9da8c99193d079d6c54b8590ea07d87fecdbf91"}, {"name": "public.m1_open_admin_session", "signature": "uuid,uuid,text,text,timestamptz", "body": "\nbegin\n  perform private.assert_server();perform private.assert_initialized();\n  if not private.active_admin_user(p_user,p_auth_session) then raise exception ''ADMIN_SESSION_FORBIDDEN'' using errcode=''42501'';end if;\n  if p_hash is null or p_hash!~''^[0-9a-f]{64}$'' or p_ciphertext is null or length(p_ciphertext) not between 20 and 32768\n    or p_expires is null or p_expires<=now() or p_expires>now()+interval ''8 hours'' then raise exception ''INVALID_ADMIN_SESSION'';end if;\n  insert into private.admin_sessions(capability_hash,user_id,auth_session_id,ciphertext,expires_at)\n    values(p_hash,p_user,p_auth_session,p_ciphertext,p_expires);\n  insert into private.audits(actor_id,action,entity_id) values(p_user::text,''ADMIN_SESSION_OPEN'',p_auth_session::text);\n  return jsonb_build_object(''created'',true,''expires_at'',p_expires);\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "cabf2d2218487409e87d5e5e14e9f883aba8b9465c81df411fc313c7152eba64"}, {"name": "public.m1_operation_status", "signature": "uuid,text", "body": "\ndeclare o private.outbox;\nbegin perform private.m1_assert_editor();\n if p_issue is null or p_effect_key is null or length(p_effect_key) not between 1 and 200 then raise exception ''INVALID_OPERATION_KEY'';end if;\n select * into o from private.outbox where issue_id=p_issue and effect_key=p_effect_key;\n if found then return jsonb_build_object(''state'',''APPLIED'',''event_type'',o.event_type,''version_id'',o.version_id);end if;\n -- Absence is not proof that an uncertain request cannot still arrive.\n return jsonb_build_object(''state'',''UNKNOWN'');\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "cb2695ee22d43c15df00a45e1a8ba9c7c266da915eb391d7b55515bbfc425b8d"}, {"name": "public.m1_preview_draft", "signature": "uuid,bigint,bigint,bigint", "body": "\ndeclare d private.editor_drafts;b jsonb;sections text[];\nbegin perform private.m1_assert_editor();select * into strict d from private.editor_drafts where issue_id=p_issue;\n  if d.revision is distinct from p_expected_revision then raise exception ''REVISION_CONFLICT'' using errcode=''40001'';end if;\n  b:=private.m1_prepare(p_issue,d.content,p_policy,p_catalog);sections:=private.visible_sections(b->>''_profile'',b,now(),now());\n  return jsonb_build_object(''title'',b->>''title'',''summary'',b->>''summary'',''body'',private.public_body(b,sections,now()),''sample_kind'',''SYNTHETIC'');\nend", "securityDefiner": true, "volatility": "v", "config": ["search_path=\"\""], "definitionSha256": "d44ba6c2b0d70fb660eff69f3798c805f4dd1d9c7633929bd0c27333514fca67"}, {"name": "public.m1_public_article", "signature": "uuid", "body": "\ndeclare r jsonb;canonical uuid;\nbegin\n  r:=public.resolve_issue(p_issue);if r->>''state''<>''PUBLISHED'' then return r;end if;\n  canonical:=(r->>''canonical_issue_id'')::uuid;\n  if not exists(select 1 from private.issues i join private.article_versions v on v.id=i.current_version_id where i.id=canonical and v.public_body->>''_contract''=''M1'') then return jsonb_build_object(''state'',''NOT_FOUND'',''message'',''현재 제공하지 않는 글'');end if;\n  if not private.m1_current_evidence(canonical) then return jsonb_build_object(''state'',''CORRECTION_PENDING'',''message'',''근거·분류 재확인 중 · 기존 내용 제공 중지'');end if;\n  return public.get_public_article(canonical);\nend", "securityDefiner": true, "volatility": "s", "config": ["search_path=\"\""], "definitionSha256": "6dda21f8f1bc0b9372025b24cf854f3ae197f768f959665e3bf0e8544d0682ad"}, {"name": "public.m1_public_articles", "signature": "uuid,int,timestamptz", "body": "\nbegin\n  if p_limit is null or p_limit not between 1 and 50 then raise exception ''INVALID_PAGE_SIZE'';end if;\n  return coalesce((select jsonb_agg(row_to_json(t)) from(\n    select n.issue_id,n.version_id,n.title,n.summary,n.first_published_at,n.material_change_at,n.sample_kind,v.public_body->>''article_kind'' article_kind,s.name sector_name\n    from public.news_public n join private.issues i on i.id=n.issue_id join private.article_versions v on v.id=n.version_id\n    left join private.sectors s on s.id=i.primary_sector_id and s.active\n    where n.publication_state=''PUBLISHED'' and private.m1_current_evidence(n.issue_id)\n      and (p_sector is null or exists(select 1 from private.impacts z where z.version_id=v.id and z.sector_id=p_sector))\n      and (p_cursor is null or n.first_published_at<p_cursor)\n    order by n.first_published_at desc,n.issue_id limit p_limit\n  )t),''[]'');\nend", "securityDefiner": true, "volatility": "s", "config"