if (select count(*) from private.view_aggregates)<>0 then raise exception 'BASELINE_ROW_COUNT';end if;
if (select count(*) from private.view_events)<>0 then raise exception 'BASELINE_ROW_COUNT';end if;
if (select count(*) from public.news_public)<>0 then raise exception 'BASELINE_ROW_COUNT';end if;

execute $c06a_source$do $$begin
 if exists(select 1 from private.sectors where sample_kind<>'SYNTHETIC') then raise exception 'CATALOG_BACKFILL_REQUIRES_REVIEW';end if;
end$$;
alter table private.sectors add column metadata_kind text not null default 'SYNTHETIC_FIXTURE';
alter table private.sectors add column catalog_kind text not null default 'LEAF' check(catalog_kind in ('PARENT','LEAF'));
alter table private.sectors alter column sample_kind drop not null;
alter table private.sectors add constraint sector_metadata_grade check(
 (metadata_kind='SYNTHETIC_FIXTURE' and sample_kind is not null and sample_kind='SYNTHETIC') or
 (metadata_kind='USER_REFERENCE_UNVERIFIED' and sample_kind is null));
alter table private.subgroups add column metadata_kind text not null default 'SYNTHETIC_FIXTURE'
 check(metadata_kind in ('SYNTHETIC_FIXTURE','USER_REFERENCE_UNVERIFIED'));
alter table private.subgroups add constraint catalog_subgroup_parent_unique unique(id,sector_id);
create table private.catalog_head (
 singleton boolean primary key default true check(singleton),
 version bigint not null references private.catalog_versions(version)
);
insert into private.catalog_head(singleton,version) select true,version from private.catalog_versions where active;
create table private.catalog_snapshots (
 version bigint primary key references private.catalog_versions(version),
 usage_scope text not null check(usage_scope in ('LEGACY_FIXTURE','LOCAL_REFERENCE')),
 document jsonb not null, sha256 text not null check(sha256 ~ '^[0-9a-f]{64}$'),
 created_at timestamptz not null default now()
);
create table private.catalog_approvals (
 version bigint primary key references private.catalog_snapshots(version),
 state text not null check(state in ('APPROVED','REVOKED'))
);
create table private.catalog_version_sectors (
 version bigint not null references private.catalog_versions(version),
 sector_id uuid not null references private.sectors(id), active boolean not null,
 catalog_kind text not null, metadata_kind text not null,
 primary key(version,sector_id)
);
create table private.catalog_source_companies (
 id uuid primary key, name text not null check(length(trim(name)) between 1 and 200),
 search_description text not null default '' check(length(search_description)<=10000),
 direct_keywords jsonb not null default '[]' check(jsonb_typeof(direct_keywords)='array'),
 industry_keywords jsonb not null default '[]' check(jsonb_typeof(industry_keywords)='array'),
 metadata_kind text not null default 'USER_REFERENCE_UNVERIFIED' check(metadata_kind='USER_REFERENCE_UNVERIFIED'),
 stock_identity_state text not null default 'UNRESOLVED' check(stock_identity_state='UNRESOLVED'),
 stock_code text check(stock_code is null), market text check(market is null),
 active boolean not null default true, source_cell text, source_row jsonb
);
create table private.catalog_memberships (
 id uuid primary key default gen_random_uuid(), sector_id uuid not null references private.sectors(id),
 subgroup_id uuid references private.subgroups(id), source_company_ref uuid not null references private.catalog_source_companies(id),
 role text check(role is null or length(role)<=10000), display_order integer not null default 0,
 active boolean not null default true,
 foreign key(subgroup_id,sector_id) references private.subgroups(id,sector_id),
 unique nulls not distinct(sector_id,subgroup_id,source_company_ref)
);
create table private.catalog_sector_data (
 sector_id uuid primary key references private.sectors(id),
 search_mapping text, search_suffix_instruction text, keywords jsonb not null default '[]',
 foreign_companies jsonb not null default '{}', source_cell text, source_row jsonb
);
create table private.catalog_raw_imports (
 source_sha256 text primary key, registry_sha256 text not null, preview_sha256 text not null,
 source_text text not null, registry_text text not null, preview_text text not null,
 initial_version bigint not null references private.catalog_versions(version), created_at timestamptz not null default now()
);
create table private.catalog_holds (
 id uuid primary key default gen_random_uuid(), source_sha256 text not null references private.catalog_raw_imports(source_sha256),
 code text not null, source_cell text, details jsonb not null,
 state text not null default 'HOLD' check(state='HOLD')
);
create table private.catalog_operations (
 operation_key text primary key check(length(operation_key) between 1 and 200),
 actor_id uuid not null, payload_sha256 text not null, version bigint not null references private.catalog_versions(version),
 result jsonb not null, created_at timestamptz not null default now()
);
do $$declare name text;begin
 foreach name in array array['catalog_head','catalog_snapshots','catalog_approvals','catalog_version_sectors','catalog_source_companies','catalog_memberships','catalog_sector_data','catalog_raw_imports','catalog_holds','catalog_operations'] loop
  execute format('alter table private.%I enable row level security',name);
  execute format('revoke all on private.%I from public,anon,authenticated',name);
 end loop;
end$$;
create function private.catalog_immutable() returns trigger language plpgsql set search_path='' as $$
begin raise exception 'IMMUTABLE_CATALOG_RECORD';end$$;
create trigger catalog_snapshot_immutable before update or delete on private.catalog_snapshots for each row execute function private.catalog_immutable();
create trigger catalog_membership_snapshot_immutable before update or delete on private.catalog_version_sectors for each row execute function private.catalog_immutable();
create trigger catalog_raw_immutable before update or delete on private.catalog_raw_imports for each row execute function private.catalog_immutable();
create trigger catalog_operation_immutable before update or delete on private.catalog_operations for each row execute function private.catalog_immutable();
create function private.catalog_snapshot_insert_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if exists(select 1 from private.catalog_snapshots where version=new.version) then raise exception 'IMMUTABLE_CATALOG_RECORD';end if;
 return new;
end$$;
create trigger catalog_membership_snapshot_insert before insert on private.catalog_version_sectors for each row execute function private.catalog_snapshot_insert_guard();
create function private.catalog_membership_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if not exists(select 1 from private.sectors where id=new.sector_id and catalog_kind='LEAF' and metadata_kind='USER_REFERENCE_UNVERIFIED')
 or (new.subgroup_id is not null and not exists(select 1 from private.subgroups where id=new.subgroup_id and sector_id=new.sector_id and metadata_kind='USER_REFERENCE_UNVERIFIED')) then raise exception 'INVALID_CATALOG_MEMBERSHIP';end if;
 if new.active and (not exists(select 1 from private.sectors where id=new.sector_id and active)
 or not exists(select 1 from private.catalog_source_companies where id=new.source_company_ref and active)
 or (new.subgroup_id is not null and not exists(select 1 from private.subgroups where id=new.subgroup_id and active))) then raise exception 'INACTIVE_CATALOG_MEMBERSHIP';end if;
 return new;
end$$;
create trigger catalog_membership_guard before insert or update on private.catalog_memberships for each row execute function private.catalog_membership_guard();
create function private.catalog_document() returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object(
 'sectors',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'description',description,'parent_id',parent_id,'display_order',display_order,'active',active,'catalog_kind',catalog_kind,'metadata_kind',metadata_kind) order by display_order,id),'[]') from private.sectors where metadata_kind='USER_REFERENCE_UNVERIFIED'),
 'subgroups',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'sector_id',sector_id,'name',name,'display_order',display_order,'active',active,'metadata_kind',metadata_kind) order by sector_id,display_order,id),'[]') from private.subgroups where metadata_kind='USER_REFERENCE_UNVERIFIED'),
 'companies',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'search_description',search_description,'direct_keywords',direct_keywords,'industry_keywords',industry_keywords,'metadata_kind',metadata_kind,'stock_identity_state',stock_identity_state,'active',active) order by id),'[]') from private.catalog_source_companies),
 'memberships',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'sector_id',sector_id,'subgroup_id',subgroup_id,'source_company_ref',source_company_ref,'role',role,'display_order',display_order,'active',active) order by sector_id,display_order,id),'[]') from private.catalog_memberships),
 'sector_data',(select coalesce(jsonb_agg(jsonb_build_object('sector_id',sector_id,'search_mapping',search_mapping,'search_suffix_instruction',search_suffix_instruction,'keywords',keywords,'foreign_companies',foreign_companies) order by sector_id),'[]') from private.catalog_sector_data))
$$;
create function private.catalog_save_snapshot(p_version bigint) returns void language plpgsql set search_path='' as $$
declare doc jsonb;
begin
 if exists(select 1 from private.catalog_snapshots where version=p_version) then raise exception 'IMMUTABLE_CATALOG_RECORD';end if;
 insert into private.catalog_version_sectors(version,sector_id,active,catalog_kind,metadata_kind)
 select p_version,id,active,catalog_kind,metadata_kind from private.sectors where metadata_kind='USER_REFERENCE_UNVERIFIED';
 doc:=private.catalog_document();
 insert into private.catalog_snapshots(version,usage_scope,document,sha256)
 values(p_version,'LOCAL_REFERENCE',doc,encode(extensions.digest(convert_to(doc::text,'UTF8'),'sha256'),'hex'));
 insert into private.catalog_approvals(version,state) values(p_version,'APPROVED');
end$$;
insert into private.catalog_version_sectors(version,sector_id,active,catalog_kind,metadata_kind)
select h.version,s.id,s.active,s.catalog_kind,s.metadata_kind from private.catalog_head h cross join private.sectors s where s.catalog_version=h.version;
insert into private.catalog_snapshots(version,usage_scope,document,sha256)
select h.version,'LEGACY_FIXTURE',d.doc,encode(extensions.digest(convert_to(d.doc::text,'UTF8'),'sha256'),'hex')
from private.catalog_head h cross join lateral (select jsonb_build_object('sectors',coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'description',s.description,'active',s.active) order by s.id),'[]')) doc from private.sectors s where s.catalog_version=h.version) d;
insert into private.catalog_approvals(version,state) select version,'APPROVED' from private.catalog_snapshots;
create function private.catalog_sector_selectable(p_sector uuid,p_catalog bigint,p_article_mode text) returns boolean language sql stable set search_path='' as $$
 select p_article_mode='SYNTHETIC'
 and exists(select 1 from private.runtime_identity where singleton and product_id='judoju-news' and environment='preview' and bootstrap_id is null and schema_version=1 and (select count(*) from private.runtime_identity)=1 and (select count(*) from judoju_control.environment_identity)=1 and exists(select 1 from judoju_control.environment_identity where singleton and product_id='judoju-news' and environment='dev' and organization_ref='qfzgicohgpuogehdyzfx' and project_ref='nxfpfvsdwbziowkxsxnh') and exists(select 1 from judoju_control.schema_artifacts where version='20261114000001' and project_ref='nxfpfvsdwbziowkxsxnh' and runtime_environment='preview' and source_sha256='5b3c2d38206dc3c43c51db287d14584b3aa72b1f54d5b2e368e252a5fcf90caa' and state='STAGED_DISABLED'))
 and exists(select 1 from private.catalog_head h join private.catalog_versions v on v.version=h.version and v.active
 join private.catalog_approvals a on a.version=h.version and a.state='APPROVED'
 join private.catalog_snapshots c on c.version=h.version
 join private.catalog_version_sectors m on m.version=h.version and m.sector_id=p_sector and m.active and m.catalog_kind='LEAF'
 join private.sectors s on s.id=m.sector_id and s.active and s.catalog_kind='LEAF' and s.catalog_version=h.version
 where h.version=p_catalog and
 ((c.usage_scope='LOCAL_REFERENCE' and m.metadata_kind='USER_REFERENCE_UNVERIFIED' and s.metadata_kind='USER_REFERENCE_UNVERIFIED' and s.sample_kind is null)
 or (c.usage_scope='LEGACY_FIXTURE' and m.metadata_kind='SYNTHETIC_FIXTURE' and s.metadata_kind='SYNTHETIC_FIXTURE' and s.sample_kind='SYNTHETIC')))
$$;
create function private.catalog_version_sector_allowed(p_catalog bigint,p_sector uuid) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from private.catalog_approvals a
 join private.catalog_version_sectors m on m.version=a.version and m.sector_id=p_sector and m.active and m.catalog_kind='LEAF'
 join private.sectors s on s.id=m.sector_id and s.active
 where a.version=p_catalog and a.state='APPROVED')
$$;
create or replace function public.m1_public_catalog() returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'description',description) order by display_order,id),'[]')
 from private.sectors where active and metadata_kind='SYNTHETIC_FIXTURE' and sample_kind='SYNTHETIC'
 and id=any(array['51000000-0000-4000-8000-000000000001','51000000-0000-4000-8000-000000000002','51000000-0000-4000-8000-000000000003']::uuid[])
$$;
create or replace function public.m1_editor_catalog() returns jsonb language plpgsql security definer set search_path='' as $$
begin perform private.m1_assert_editor();return public.m1_public_catalog();end$$;
create or replace function private.m1_prepare_v1(p_issue uuid,p_input jsonb,p_policy bigint,p_catalog bigint) returns jsonb language plpgsql stable set search_path='' as $$
declare b jsonb:=p_input;x jsonb;e uuid;sector uuid;path text;direction text;cd text;positive text[]:='{}';negative text[]:='{}';
  benefit jsonb:='[]';damage jsonb:='[]';related jsonb:='[]';all_sectors jsonb:='[]';impacts jsonb:='[]';scenarios jsonb;profile text;
  pos_count integer;neg_count integer;title text;valid boolean;seen text[]:='{}';key text;schedules jsonb:='[]';kind text;tz text;start_at timestamptz;end_at timestamptz;
begin
  if b is null or jsonb_typeof(b)<>'object' or pg_column_size(b)>131072 then raise exception 'INVALID_EDITOR_CONTENT';end if;
  if b ? 'scheduled_publish_at' or b ? 'sample_kind' and b->>'sample_kind'<>'SYNTHETIC' then raise exception 'RESERVATION_OR_REAL_MODE_NOT_ENABLED';end if;
  if not exists(select 1 from private.policies where version=p_policy and active) or not exists(select 1 from private.catalog_versions where version=p_catalog and active) then raise exception 'STALE_POLICY_OR_CATALOG';end if;
  if not exists(select 1 from private.issues where id=p_issue and sample_kind='SYNTHETIC') then raise exception 'SYNTHETIC_ISSUE_REQUIRED';end if;
  if length(trim(coalesce(b->>'title',''))) not between 1 and 200 or length(trim(coalesce(b->>'summary',''))) not between 1 and 1500
    or length(trim(coalesce(b->>'issue_analysis',''))) not between 1 and 20000 then raise exception 'CORE_TEXT_REQUIRED';end if;
  if coalesce(b->>'article_kind','') not in ('SECTOR','MACRO') or coalesce(b->>'source_market','') not in ('KR','US','GLOBAL','SYNTHETIC') or coalesce(b->>'selection_market_basis','') not in ('KR','FOREIGN_US') then raise exception 'ARTICLE_MARKET_REQUIRED';end if;
  if b ? 'analysis_perspective' and b->>'analysis_perspective'<>'KR_EQUITY' then raise exception 'KR_PERSPECTIVE_REQUIRED';end if;
  sector:=nullif(b->>'primary_sector_id','')::uuid;
  if b->>'article_kind'='SECTOR' and sector is null then raise exception 'PRIMARY_SECTOR_REQUIRED';end if;
  if sector is not null and not private.catalog_sector_selectable(sector,p_catalog,'SYNTHETIC') then raise exception 'PRIMARY_SECTOR_INACTIVE';end if;
  if jsonb_typeof(b->'key_issues') is distinct from 'array' or jsonb_array_length(b->'key_issues') not between 1 and 12 then raise exception 'KEY_ISSUES_REQUIRED';end if;
  for x in select value from jsonb_array_elements(b->'key_issues') loop if jsonb_typeof(x)<>'string' or length(trim(x#>>'{}')) not between 1 and 1000 then raise exception 'INVALID_KEY_ISSUE';end if;end loop;
  if jsonb_typeof(b->'sources') is distinct from 'array' or jsonb_array_length(b->'sources') not between 1 and 12 then raise exception 'SOURCES_REQUIRED';end if;
  for x in select value from jsonb_array_elements(b->'sources') loop
    if length(trim(coalesce(x->>'name',''))) not between 1 and 100 or coalesce(x->>'url','')!~'^https://[a-z0-9.-]+\.invalid(/[^[:space:]]*)?$' or length(x->>'url')>2048 then raise exception 'SYNTHETIC_SOURCE_REQUIRED';end if;
  end loop;
  if jsonb_typeof(b->'impacts') is distinct from 'array' or jsonb_array_length(b->'impacts') not between 1 and 30 then raise exception 'KR_IMPACT_PATH_REQUIRED';end if;
  for x in select value from jsonb_array_elements(b->'impacts') loop
    sector:=(x->>'sector_id')::uuid;path:=x->>'path_id';direction:=x->>'direction';cd:=coalesce(x->>'conditional_direction','NONE');
    if sector is null or not private.catalog_sector_selectable(sector,p_catalog,'SYNTHETIC') then raise exception 'IMPACT_SECTOR_INACTIVE';end if;
    if path is null or path!~'^[A-Za-z0-9_-]{1,80}$' or coalesce(direction,'') not in ('BENEFIT','DAMAGE','RELATED') or cd not in ('NONE','POSITIVE','NEGATIVE') or direction<>'RELATED' and cd<>'NONE' then raise exception 'INVALID_IMPACT_PATH';end if;
    key:=sector::text||':'||path;if key=any(seen) then raise exception 'DUPLICATE_SECTOR_PATH';end if;seen:=array_append(seen,key);
    if length(trim(coalesce(x->>'description',''))) not between 1 and 1500 then raise exception 'IMPACT_DESCRIPTION_REQUIRED';end if;
    if jsonb_typeof(x->'evidence_ids') is distinct from 'array' or jsonb_array_length(x->'evidence_ids') not between 1 and 10 then raise exception 'PATH_EVIDENCE_REQUIRED';end if;
    for e in select value::uuid from jsonb_array_elements_text(x->'evidence_ids') loop
      if e is null or not exists(select 1 from private.claims where id=e and issue_id=p_issue and verified and korea_path_verified and fact_current and sample_kind='SYNTHETIC' and claim_type<>'SENSITIVE_UNCONFIRMED' and (valid_until is null or valid_until>now())) then raise exception 'PATH_EVIDENCE_NOT_VERIFIED';end if;
    end loop;
    if jsonb_typeof(coalesce(x->'conditions','[]'))<>'array' or direction='RELATED' and cd<>'NONE' and jsonb_array_length(coalesce(x->'conditions','[]'))=0 then raise exception 'PATH_CONDITION_REQUIRED';end if;
    if direction='BENEFIT' or cd='POSITIVE' then positive:=array_append(positive,path);end if;
    if direction='DAMAGE' or cd='NEGATIVE' then negative:=array_append(negative,path);end if;
    if direction='BENEFIT' then benefit:=benefit||jsonb_build_array(sector);elsif direction='DAMAGE' then damage:=damage||jsonb_build_array(sector);else related:=related||jsonb_build_array(sector);end if;
    all_sectors:=all_sectors||jsonb_build_array(sector);
    impacts:=impacts||jsonb_build_array(jsonb_build_object('sector_id',sector,'path_id',path,'direction',direction,'conditional_direction',cd,'description',x->>'description','conditions',coalesce(x->'conditions','[]'),'evidence_ids',x->'evidence_ids'));
  end loop;
  if jsonb_array_length(benefit)=0 and jsonb_array_length(damage)=0 then profile:='RELATED_CONDITIONAL';
  elsif cardinality(positive)>0 and cardinality(negative)>0 then profile:='POSITIVE_NEGATIVE';
  elsif cardinality(positive)>0 then profile:='POSITIVE_ONLY';else profile:='DAMAGE_ONLY';end if;
  scenarios:=coalesce(b->'scenarios','[]');if jsonb_typeof(scenarios)<>'array' then raise exception 'INVALID_SCENARIOS';end if;
  select count(*) filter(where value->>'direction'='POSITIVE'),count(*) filter(where value->>'direction'='NEGATIVE') into pos_count,neg_count from jsonb_array_elements(scenarios);
  if cardinality(positive)=0 then
    if jsonb_array_length(scenarios)<>0 then raise exception 'NO_POSITIVE_PATH_NO_SCENARIOS';end if;
  elsif pos_count<>1 or neg_count<>(case when cardinality(negative)>0 then 1 else 0 end) or jsonb_array_length(scenarios)<>pos_count+neg_count then raise exception 'SCENARIO_PATH_MISMATCH';end if;
  for x in select value from jsonb_array_elements(scenarios) loop
    if length(trim(coalesce(x->>'title',''))) not between 1 and 200 or length(trim(coalesce(x->>'expected_result',''))) not between 1 and 2000 or jsonb_typeof(x->'checks') is distinct from 'array' or jsonb_array_length(x->'checks')=0
      or jsonb_typeof(x->'path_ids') is distinct from 'array' or jsonb_array_length(x->'path_ids')=0 then raise exception 'SCENARIO_CONTENT_REQUIRED';end if;
    for path in select value from jsonb_array_elements_text(x->'path_ids') loop
      if path is null or not path=any(case when x->>'direction'='POSITIVE' then positive else negative end) then raise exception 'SCENARIO_EVIDENCE_PATH_MISMATCH';end if;
    end loop;
  end loop;
  if jsonb_typeof(coalesce(b->'risks','[]'))<>'array' then raise exception 'INVALID_RISKS';end if;
  if profile='DAMAGE_ONLY' and jsonb_array_length(coalesce(b->'risks','[]'))=0 then raise exception 'DAMAGE_REQUIRES_RISKS';end if;
  if jsonb_typeof(coalesce(b->'schedule','[]'))<>'array' then raise exception 'INVALID_SCHEDULE';end if;
  for x in select value from jsonb_array_elements(coalesce(b->'schedule','[]')) loop
    if coalesce(x->>'status','') not in ('VERIFIED','CANCELLED','UNVERIFIED','SUPERSEDED') then raise exception 'SCHEDULE_STATUS_REQUIRED';end if;
    if x->>'status'='VERIFIED' then
      kind:=x->>'kind';tz:=x->>'timezone';
      if coalesce(kind,'') not in ('EXACT','PERIOD') or not exists(select 1 from pg_catalog.pg_timezone_names where name=tz) or length(trim(coalesce(x->>'title',''))) not between 1 and 200 or nullif(x->>'evidence_as_of','')::timestamptz is null or (x->>'evidence_as_of')::timestamptz>now() then raise exception 'SCHEDULE_VERIFICATION_REQUIRED';end if;
      if jsonb_typeof(x->'evidence_ids') is distinct from 'array' or jsonb_array_length(x->'evidence_ids')=0 then raise exception 'SCHEDULE_EVIDENCE_REQUIRED';end if;
      for e in select value::uuid from jsonb_array_elements_text(x->'evidence_ids') loop
        if not exists(select 1 from private.claims where id=e and issue_id=p_issue and verified and fact_current and official_original and (valid_until is null or valid_until>now())) then raise exception 'SCHEDULE_OFFICIAL_EVIDENCE_REQUIRED';end if;
      end loop;
      if kind='EXACT' then
        if nullif(x->>'event_at','')::timestamptz is null then raise exception 'SCHEDULE_INSTANT_REQUIRED';end if;
      else
        start_at:=nullif(x->>'period_start','')::timestamptz;end_at:=nullif(x->>'period_end','')::timestamptz;
        if start_at is null or end_at is null or start_at>=end_at or length(trim(coalesce(x->>'period_label',''))) not between 1 and 100 or length(trim(coalesce(x->>'precision',''))) not between 1 and 40 or x ? 'event_at' then raise exception 'SCHEDULE_PERIOD_REQUIRED';end if;
      end if;
    end if;
    schedules:=schedules||jsonb_build_array(x);
  end loop;
  return jsonb_build_object('_contract','M1','_profile',profile,'_positive_paths',to_jsonb(positive),'_negative_paths',to_jsonb(negative),
    'title',b->>'title','summary',b->>'summary','article_kind',b->>'article_kind','primary_sector_id',nullif(b->>'primary_sector_id','')::uuid,
    'source_market',b->>'source_market','selection_market_basis',b->>'selection_market_basis','analysis_perspective','KR_EQUITY',
    'key_issues',b->'key_issues','issue_analysis',b->>'issue_analysis','sources',b->'sources','scenarios',scenarios,'impacts',impacts,
    'benefit_sector_ids',benefit,'damage_sector_ids',damage,'related_sector_ids',related,'filter_sector_ids',all_sectors,'risks',coalesce(b->'risks','[]'),'schedule',schedules);
end$$;
create or replace function private.catalog_version_sector_allowed(p_catalog bigint,p_sector uuid) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from private.catalog_approvals a
 join private.catalog_version_sectors m on m.version=a.version and m.sector_id=p_sector and m.active and m.catalog_kind='LEAF'
 join private.sectors s on s.id=m.sector_id and s.active and s.catalog_kind='LEAF' and s.metadata_kind=m.metadata_kind
 where a.version=p_catalog and a.state='APPROVED')
$$;
create or replace function private.m1_current_evidence(p_issue uuid) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from private.issues i join private.article_versions v on v.id=i.current_version_id
 where i.id=p_issue and i.publication_state='PUBLISHED' and i.sample_kind='SYNTHETIC' and v.public_body->>'_contract'='M1'
 and exists(select 1 from private.policies p where p.version=v.visibility_policy_version and p.active)
 and exists(select 1 from private.catalog_approvals a where a.version=v.catalog_version and a.state='APPROVED')
 and exists(select 1 from private.impacts z where z.version_id=v.id)
 and not exists(select 1 from private.claims c where c.issue_id=i.id and (not c.verified or not c.fact_current or not c.korea_path_verified or c.claim_type='SENSITIVE_UNCONFIRMED' or c.valid_until<=now()))
 and (i.primary_sector_id is null or private.catalog_version_sector_allowed(v.catalog_version,i.primary_sector_id))
 and not exists(select 1 from private.impacts z where z.version_id=v.id and not private.catalog_version_sector_allowed(v.catalog_version,z.sector_id))
 and not exists(select 1 from private.impacts z where z.version_id=v.id and cardinality(z.evidence_ids)=0)
 and not exists(select 1 from private.impacts z cross join lateral unnest(z.evidence_ids) e(id)
 left join private.claims c on c.id=e.id and c.issue_id=i.id
 where z.version_id=v.id and (c.id is null or not c.verified or not c.fact_current or not c.korea_path_verified or c.valid_until<=now()))
 and private.m1_core_evidence(i.id,v.public_body->>'article_kind'))
$$;
create or replace function public.m1_publish_draft(p_issue uuid,p_expected_revision bigint,p_issue_revision bigint,p_policy bigint,p_catalog bigint,p_effect_key text) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 perform private.m1_assert_editor();perform 1 from private.catalog_head where singleton for share;
 perform 1 from private.issues where id=p_issue for update;
 return private.m1_publish_draft_v1(p_issue,p_expected_revision,p_issue_revision,p_policy,p_catalog,p_effect_key);
end$$;
create function private.catalog_seed_reference(p_source_text text,p_registry_text text,p_preview_text text) returns jsonb language plpgsql set search_path='' as $$
declare src text;reg text;pre text;s jsonb;r jsonb;p jsonb;x jsonb;g jsonb;m jsonb;c jsonb;v bigint;position integer;old private.catalog_raw_imports;
begin
 perform private.assert_initialized();
 if current_user<>'postgres' or not exists(select 1 from private.runtime_identity where product_id='judoju-news' and environment='local' and bootstrap_id is not null) then raise exception 'LOCAL_POSTGRES_BOOTSTRAP_ONLY';end if;
 src:=encode(extensions.digest(convert_to(p_source_text,'UTF8'),'sha256'),'hex');
 reg:=encode(extensions.digest(convert_to(p_registry_text,'UTF8'),'sha256'),'hex');
 pre:=encode(extensions.digest(convert_to(p_preview_text,'UTF8'),'sha256'),'hex');
 if src<>'5c86278ab12d16979a1f5fd7a100e15368db2450f1ebcf47e70aced66d84a5d2'
 or reg<>'160a969756bfd291c81dda390a3490f46ac60bc12eed262e1818e5ba40a03dc6'
 or pre<>'10151662655abf5fd5ba1c09c30e8b91b07ab1549afbb4257c978544d92edb0d' then raise exception 'UNREVIEWED_CATALOG_INPUT';end if;
 select version into v from private.catalog_head where singleton for update;
 select * into old from private.catalog_raw_imports where source_sha256=src;
 if found then
  if old.registry_sha256<>reg or old.preview_sha256<>pre then raise exception 'CATALOG_IMPORT_CONFLICT';end if;
  return jsonb_build_object('status','ALREADY_APPLIED','initial_version',old.initial_version,'current_version',v);
 end if;
 if not exists(select 1 from private.catalog_snapshots where version=v and usage_scope='LEGACY_FIXTURE') then raise exception 'INITIAL_IMPORT_ALREADY_COMPLETED';end if;
 s:=p_source_text::jsonb;r:=p_registry_text::jsonb;p:=p_preview_text::jsonb;
 if p->>'mode' is distinct from 'OFFLINE_PREVIEW_ONLY' or p->'importable' is distinct from 'false'::jsonb
 or p->>'sourceSha256' is distinct from src or p->'rawSource' is distinct from s
 or jsonb_array_length(p->'categories')<>56 or jsonb_array_length(p->'companies')<>339
 or jsonb_array_length(r->'parents')<>11 or jsonb_array_length(r->'subgroups')<>81
 or jsonb_array_length(p->'unresolved')<>341 or jsonb_array_length(p->'differences')<>0
 or (p->'summary'->>'structuralHoldCount')::integer<>2 then raise exception 'CATALOG_PREVIEW_REQUIRES_REVIEW';end if;
 if exists(select 1 from jsonb_array_elements(p->'categories') x cross join lateral jsonb_array_elements(x->'subgroups') g
 where g->>'state' is distinct from 'PARSED_SOURCE' or g->>'id' is null)
 or exists(select 1 from jsonb_array_elements(p->'categories') x cross join lateral jsonb_array_elements(x->'memberships') m
 where m->>'state' is distinct from 'PARSED_SOURCE' or m->'exactMembershipDuplicate' is distinct from 'false'::jsonb)
 or exists(select 1 from jsonb_array_elements(p->'companies') c where c->'stockIdentity'->>'state' is distinct from 'UNRESOLVED'
 or c->'stockIdentity'->'code' is distinct from 'null'::jsonb or c->'price' is distinct from 'null'::jsonb or c->'stockUrl' is distinct from 'null'::jsonb)
 then raise exception 'CATALOG_PREVIEW_REQUIRES_REVIEW';end if;
 if exists(select 1 from jsonb_array_elements((r->'parents')||(r->'categories')) x join private.sectors z on z.id=(x->>'id')::uuid)
 or exists(select 1 from jsonb_array_elements(r->'subgroups') x join private.subgroups z on z.id=(x->>'id')::uuid)
 or exists(select 1 from jsonb_array_elements(r->'companies') x join private.catalog_source_companies z on z.id=(x->>'id')::uuid)
 then raise exception 'DO_NOT_ADOPT_EXISTING_CATALOG_ID';end if;
 select coalesce(max(version),0)+1 into v from private.catalog_versions;
 update private.catalog_versions set active=false where active;
 insert into private.catalog_versions(version,active) values(v,true);
 position:=0;
 for x in select value from jsonb_array_elements(r->'parents') loop
  insert into private.sectors(id,name,description,parent_id,display_order,catalog_version,sample_kind,metadata_kind,catalog_kind)
  values((x->>'id')::uuid,x->>'name','',null,position,v,null,'USER_REFERENCE_UNVERIFIED','PARENT');position:=position+1;
 end loop;
 position:=0;
 for x in select value from jsonb_array_elements(p->'categories') loop
  insert into private.sectors(id,name,description,parent_id,display_order,catalog_version,sample_kind,metadata_kind,catalog_kind)
  values((x->>'id')::uuid,x->>'name',coalesce(x->>'detailDescription',''),(x->>'parentId')::uuid,(x->>'sourceRow')::integer-2,v,null,'USER_REFERENCE_UNVERIFIED','LEAF');
  insert into private.catalog_sector_data(sector_id,search_mapping,search_suffix_instruction,keywords,foreign_companies,source_cell,source_row)
  values((x->>'id')::uuid,x->>'categorySearchMapping',x->>'categorySearchSuffixInstruction',x->'keywords',x->'foreignCompanies',x->>'sourceCell',x->'rawRow');
  position:=0;
  for g in select value from jsonb_array_elements(x->'subgroups') loop
   insert into private.subgroups(id,sector_id,name,display_order,metadata_kind)
   values((g->>'id')::uuid,(x->>'id')::uuid,g->>'title',position,'USER_REFERENCE_UNVERIFIED');position:=position+1;
  end loop;
 end loop;
 for c in select value from jsonb_array_elements(p->'companies') loop
  insert into private.catalog_source_companies(id,name,search_description,direct_keywords,industry_keywords,source_cell,source_row)
  values((c->>'sourceCompanyRef')::uuid,c->>'name',coalesce(c->>'searchDescription',''),c->'directSearchKeywords'->'entries',c->'industrySearchKeywords'->'entries',c->>'sourceCell',c->'rawRow');
 end loop;
 for x in select value from jsonb_array_elements(p->'categories') loop
  position:=0;
  for m in select value from jsonb_array_elements(x->'memberships') loop
   insert into private.catalog_memberships(sector_id,subgroup_id,source_company_ref,role,display_order)
   values((x->>'id')::uuid,(m->>'subgroupId')::uuid,(m->>'sourceCompanyRef')::uuid,m->>'role',position);position:=position+1;
  end loop;
 end loop;
 insert into private.catalog_raw_imports(source_sha256,registry_sha256,preview_sha256,source_text,registry_text,preview_text,initial_version)
 values(src,reg,pre,p_source_text,p_registry_text,p_preview_text,v);
 for x in select value from jsonb_array_elements(p->'unresolved') loop
  insert into private.catalog_holds(source_sha256,code,source_cell,details) values(src,x->>'code',x->>'cell',x);
 end loop;
 update private.catalog_head set version=v where singleton;
 perform private.catalog_save_snapshot(v);
 insert into private.audits(actor_id,action,entity_id,details) values('local-reviewed-bootstrap','CATALOG_REFERENCE_SEED',v::text,jsonb_build_object('source_sha256',src,'company_records',339,'structural_holds',2,'stock_identity_holds',339));
 insert into private.outbox(event_type,effect_key,payload) values('CATALOG_CHANGED','catalog:seed:'||src,jsonb_build_object('catalog_version',v,'metadata_kind','USER_REFERENCE_UNVERIFIED','catalog_request_hash',pre));
 return jsonb_build_object('status','APPLIED','version',v,'categories',56,'company_records',339,'subgroups',81,'memberships',364,'holds',341,'real_publication_enabled',false);
end$$;
