create or replace function private.catalog_sector_selectable(p_sector uuid,p_catalog bigint,p_article_mode text) returns boolean language sql stable set search_path='' as $$
 select p_article_mode='SYNTHETIC'
 and exists(select 1 from private.runtime_identity where singleton and product_id='judoju-news' and environment='preview' and bootstrap_id is null and schema_version=1 and (select count(*) from private.runtime_identity)=1 and (select count(*) from judoju_control.environment_identity)=1 and exists(select 1 from judoju_control.environment_identity where singleton and product_id='judoju-news' and environment='dev' and organization_ref='qfzgicohgpuogehdyzfx' and project_ref='nxfpfvsdwbziowkxsxnh') and exists(select 1 from judoju_control.schema_artifacts where version='20261114000001' and project_ref='nxfpfvsdwbziowkxsxnh' and runtime_environment='preview' and source_sha256='5b3c2d38206dc3c43c51db287d14584b3aa72b1f54d5b2e368e252a5fcf90caa' and state='STAGED_DISABLED'))
 and exists(select 1 from private.catalog_head h join private.catalog_versions v on v.version=h.version and v.active
 join private.catalog_approvals a on a.version=h.version and a.state='APPROVED'
 join private.catalog_snapshots c on c.version=h.version
 join private.catalog_version_sectors m on m.version=h.version and m.sector_id=p_sector and m.active and m.catalog_kind='LEAF'
 join private.sectors s on s.id=m.sector_id and s.active and s.catalog_kind='LEAF' and s.catalog_version=h.version
 left join private.sectors parent on parent.id=s.parent_id
 where h.version=p_catalog and
 ((c.usage_scope='LOCAL_REFERENCE' and m.metadata_kind='USER_REFERENCE_UNVERIFIED' and s.metadata_kind='USER_REFERENCE_UNVERIFIED' and s.sample_kind is null
 and parent.active and parent.catalog_kind='PARENT' and parent.metadata_kind='USER_REFERENCE_UNVERIFIED' and parent.catalog_version=h.version)
 or (c.usage_scope='LEGACY_FIXTURE' and m.metadata_kind='SYNTHETIC_FIXTURE' and s.metadata_kind='SYNTHETIC_FIXTURE' and s.sample_kind='SYNTHETIC')))
$$;
create or replace function private.catalog_version_sector_allowed(p_catalog bigint,p_sector uuid) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from private.catalog_approvals a
 join private.catalog_version_sectors m on m.version=a.version and m.sector_id=p_sector and m.active and m.catalog_kind='LEAF'
 join private.sectors s on s.id=m.sector_id and s.active and s.catalog_kind='LEAF' and s.metadata_kind=m.metadata_kind
 left join private.sectors parent on parent.id=s.parent_id
 where a.version=p_catalog and a.state='APPROVED'
 and (s.metadata_kind='SYNTHETIC_FIXTURE' or parent.active and parent.catalog_kind='PARENT' and parent.metadata_kind='USER_REFERENCE_UNVERIFIED'))
$$;
create function private.catalog_require_reference_head(p_expected bigint) returns bigint language plpgsql stable set search_path='' as $$
declare head bigint;
begin
 perform private.assert_initialized();
 select h.version into head from private.catalog_head h join private.catalog_versions v on v.version=h.version and v.active
 join private.catalog_approvals a on a.version=h.version and a.state='APPROVED'
 join private.catalog_snapshots s on s.version=h.version and s.usage_scope='LOCAL_REFERENCE';
 if head is null then raise exception 'CATALOG_NOT_READY';end if;
 if p_expected is not null and p_expected<>head then raise exception 'STALE_CATALOG';end if;
 return head;
end$$;
create function private.catalog_tree(p_head bigint) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('catalog_version',p_head::text,'metadata_kind','USER_REFERENCE_UNVERIFIED','parents',coalesce(jsonb_agg(
 jsonb_build_object('id',parent.id,'name',parent.name,'order',parent.display_order,'sectors',
 (select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'description',s.description,'parent_id',s.parent_id,'order',s.display_order) order by s.display_order,s.id),'[]')
 from private.sectors s where s.parent_id=parent.id and private.catalog_sector_selectable(s.id,p_head,'SYNTHETIC')))
 order by parent.display_order,parent.id),'[]'))
 from private.sectors parent where parent.metadata_kind='USER_REFERENCE_UNVERIFIED' and parent.catalog_kind='PARENT' and parent.active and parent.catalog_version=p_head
$$;
create function private.catalog_public_members(p_sector uuid,p_group uuid) returns jsonb language sql stable set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('membership_id',m.id,'source_company_ref',c.id,'name',c.name,'description',coalesce(m.role,''),
 'stock_identity_state',c.stock_identity_state,'stock_code',null,'price',null,'change_percent',null,'stock_url',null)
 order by m.display_order,m.id),'[]')
 from private.catalog_memberships m join private.catalog_source_companies c on c.id=m.source_company_ref and c.active
 where m.sector_id=p_sector and m.subgroup_id is not distinct from p_group and m.active
$$;
create function public.catalog_public_tree(p_expected bigint default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;
begin head:=private.catalog_require_reference_head(p_expected);return private.catalog_tree(head);end$$;
create function public.catalog_public_sector(p_sector uuid,p_expected bigint default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;sector private.sectors;groups jsonb;
begin
 head:=private.catalog_require_reference_head(p_expected);
 if not private.catalog_sector_selectable(p_sector,head,'SYNTHETIC') then return jsonb_build_object('state','NOT_FOUND','catalog_version',head::text);end if;
 select * into sector from private.sectors where id=p_sector;
 select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'order',g.display_order,'members',private.catalog_public_members(p_sector,g.id)) order by g.display_order,g.id),'[]') into groups
 from private.subgroups g where g.sector_id=p_sector and g.active and g.metadata_kind='USER_REFERENCE_UNVERIFIED';
 return jsonb_build_object('state','AVAILABLE','catalog_version',head::text,'id',sector.id,'name',sector.name,'description',sector.description,
 'parent_id',sector.parent_id,'metadata_kind',sector.metadata_kind,'groups',groups,'ungrouped_members',private.catalog_public_members(p_sector,null));
end$$;
create function public.catalog_editor_tree(p_expected bigint default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;
begin perform private.m1_assert_editor();head:=private.catalog_require_reference_head(p_expected);return private.catalog_tree(head)||jsonb_build_object('actor_id',auth.uid());end$$;
create function public.catalog_editor_sectors() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;
begin
 perform private.m1_assert_editor();head:=private.catalog_require_reference_head(null);
 return jsonb_build_object('catalog_version',head::text,'sectors',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'description',s.description) order by s.display_order,s.id),'[]') from private.sectors s where private.catalog_sector_selectable(s.id,head,'SYNTHETIC')));
end$$;
create or replace function public.m1_save_draft(p_issue uuid,p_expected_revision bigint,p_content jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
begin perform private.m1_assert_editor();perform 1 from private.catalog_head where singleton for share;
perform 1 from private.issues where id=p_issue for update;
return private.m1_save_draft_v1(p_issue,p_expected_revision,p_content);end$$;
create function private.catalog_label(p_text text,p_max integer default 200) returns text language plpgsql immutable set search_path='' as $$
declare value text;spaces text:=' '||chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||U&'\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF';
begin
 value:=normalize(btrim(p_text,spaces),NFC);
 if value is null or length(value) not between 1 and p_max then raise exception 'INVALID_CATALOG_TEXT';end if;
 return value;
end$$;
create function private.catalog_assert_payload(p_payload jsonb,p_allowed text[],p_required text[] default '{}') returns void language plpgsql immutable set search_path='' as $$
begin
 if jsonb_typeof(p_payload) is distinct from 'object' or pg_column_size(p_payload)>131072 then raise exception 'INVALID_CATALOG_PAYLOAD';end if;
 if exists(select 1 from jsonb_object_keys(p_payload) field_name where not field_name=any(p_allowed)) then raise exception 'CATALOG_FIELD_NOT_ALLOWED';end if;
 if exists(select 1 from unnest(p_required) field_name where not p_payload ? field_name) then raise exception 'CATALOG_FIELD_REQUIRED';end if;
end$$;
create function private.catalog_order(p_value jsonb,p_default integer default 0) returns integer language plpgsql immutable set search_path='' as $$
begin
 if p_value is null then return p_default;end if;
 if jsonb_typeof(p_value)<>'number' or (p_value#>>'{}')!~'^[0-9]{1,7}$' or (p_value#>>'{}')::integer>1000000 then raise exception 'INVALID_CATALOG_ORDER';end if;
 return (p_value#>>'{}')::integer;
end$$;
create function private.catalog_terms(p_terms jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare term jsonb;result jsonb:='[]';label text;
begin
 if jsonb_typeof(p_terms) is distinct from 'array' or jsonb_array_length(p_terms)>200 then raise exception 'INVALID_CATALOG_KEYWORDS';end if;
 for term in select value from jsonb_array_elements(p_terms) loop
  if jsonb_typeof(term)<>'string' then raise exception 'INVALID_CATALOG_KEYWORDS';end if;
  label:=private.catalog_label(term#>>'{}',100);
  if label~E'[\n\r]' then raise exception 'INVALID_CATALOG_KEYWORDS';end if;
  result:=result||jsonb_build_array(jsonb_build_object('raw',term#>>'{}','value',btrim(term#>>'{}'),'comparisonKey',label,'origin','ADMIN'));
 end loop;
 return result;
end$$;
create function private.catalog_keyword_kind(p_entry jsonb) returns text language sql immutable set search_path='' as $$
 select coalesce(p_entry->>'kind',case left(p_entry->>'cell',1) when 'F' then 'INDUSTRY' when 'G' then 'CORE' else 'ADDITIONAL' end)
$$;
create function private.catalog_affected_issues(p_sector_ids uuid[]) returns uuid[] language sql volatile set search_path='' as $$
 select coalesce(array_agg(i.id order by i.id),'{}') from private.issues i
 where i.primary_sector_id=any(p_sector_ids)
 or exists(select 1 from private.impacts z where z.version_id=i.current_version_id and z.sector_id=any(p_sector_ids))
 or exists(select 1 from private.editor_drafts d where d.issue_id=i.id and (
 d.content->>'primary_sector_id'=any(array(select id::text from unnest(p_sector_ids) id))
 or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(d.content->'impacts')='array' then d.content->'impacts' else '[]' end) path_entry
 where path_entry->>'sector_id'=any(array(select id::text from unnest(p_sector_ids) id)))))
$$;
create function private.catalog_impact(p_sector uuid) returns jsonb language plpgsql set search_path='' as $$
declare sector_ids uuid[];issue_ids uuid[];doc jsonb;head bigint;
begin
 head:=private.catalog_require_reference_head(null);
 if not exists(select 1 from private.sectors where id=p_sector and metadata_kind='USER_REFERENCE_UNVERIFIED') then raise exception 'CATALOG_ENTITY_NOT_FOUND';end if;
 select array_agg(id order by id) into sector_ids from private.sectors where metadata_kind='USER_REFERENCE_UNVERIFIED' and (id=p_sector or parent_id=p_sector);
 issue_ids:=private.catalog_affected_issues(sector_ids);
 doc:=jsonb_build_object('catalog_version',head::text,'sector_id',p_sector,
 'sectors',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'active',active) order by id),'[]') from private.sectors where id=any(sector_ids)),
 'groups',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'active',active) order by id),'[]') from private.subgroups where sector_id=any(sector_ids) and metadata_kind='USER_REFERENCE_UNVERIFIED'),
 'memberships',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'active',active) order by id),'[]') from private.catalog_memberships where sector_id=any(sector_ids)),
 'issues',(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'revision',i.revision,'state',i.publication_state,'version_id',i.current_version_id,'draft_revision',d.revision,'scheduled_publish_at',i.scheduled_publish_at) order by i.id),'[]') from private.issues i left join private.editor_drafts d on d.issue_id=i.id where i.id=any(issue_ids)));
 return jsonb_build_object('catalog_version',head::text,'impact_sha256',encode(extensions.digest(convert_to(doc::text,'UTF8'),'sha256'),'hex'),
 'sector_count',cardinality(sector_ids),'active_group_count',(select count(*) from private.subgroups where sector_id=any(sector_ids) and active),
 'active_membership_count',(select count(*) from private.catalog_memberships where sector_id=any(sector_ids) and active),
 'issue_count',cardinality(issue_ids),'published_count',(select count(*) from private.issues where id=any(issue_ids) and publication_state='PUBLISHED'),
 'draft_count',(select count(*) from private.editor_drafts where issue_id=any(issue_ids)),
 'scheduled_count',(select count(*) from private.issues where id=any(issue_ids) and scheduled_publish_at is not null),
 'examples',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'state',e.publication_state,'title',e.title) order by e.id),'[]') from (select i.id,i.publication_state,coalesce(d.content->>'title',v.title,'') title from private.issues i left join private.editor_drafts d on d.issue_id=i.id left join private.article_versions v on v.id=i.current_version_id where i.id=any(issue_ids) order by i.id limit 20)e));
end$$;
create function public.catalog_editor_impact(p_sector uuid,p_expected bigint) returns jsonb language plpgsql security definer set search_path='' as $$
begin perform private.m1_assert_editor();perform private.catalog_require_reference_head(p_expected);return private.catalog_impact(p_sector);end$$;
create function public.catalog_editor_sector(p_sector uuid,p_expected bigint default null,p_offset integer default 0,p_limit integer default 50) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;sector_data jsonb;groups jsonb;members jsonb;count_members bigint;
begin
 perform private.m1_assert_editor();head:=private.catalog_require_reference_head(p_expected);
 if p_offset is null or p_offset not between 0 and 100000 or p_limit is null or p_limit not between 1 and 100 then raise exception 'INVALID_PAGE_SIZE';end if;
 select to_jsonb(s)-'sample_kind'-'catalog_version' into sector_data from private.sectors s where s.id=p_sector and s.metadata_kind='USER_REFERENCE_UNVERIFIED';
 if sector_data is null then raise exception 'CATALOG_ENTITY_NOT_FOUND';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'order',g.display_order,'active',g.active) order by g.display_order,g.id),'[]') into groups from private.subgroups g where g.sector_id=p_sector and g.metadata_kind='USER_REFERENCE_UNVERIFIED';
 select count(*) into count_members from private.catalog_memberships where sector_id=p_sector;
 select coalesce(jsonb_agg(to_jsonb(page) order by page.display_order,page.id),'[]') into members from
 (select m.id,m.subgroup_id,m.source_company_ref,m.role,m.display_order,m.active,c.name,c.active company_active
 from private.catalog_memberships m join private.catalog_source_companies c on c.id=m.source_company_ref where m.sector_id=p_sector order by m.display_order,m.id limit p_limit offset p_offset)page;
 return jsonb_build_object('catalog_version',head::text,'sector',sector_data,'groups',groups,'memberships',members,'total_memberships',count_members,'offset',p_offset,'limit',p_limit,
 'keyword_settings',(select to_jsonb(d)-'source_row' from private.catalog_sector_data d where d.sector_id=p_sector));
end$$;
create function public.catalog_editor_companies(p_offset integer default 0,p_limit integer default 50,p_query text default '') returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;items jsonb;total bigint;
begin
 perform private.m1_assert_editor();head:=private.catalog_require_reference_head(null);
 if p_offset is null or p_offset not between 0 and 100000 or p_limit is null or p_limit not between 1 and 100 or p_query is null or length(p_query)>200 then raise exception 'INVALID_PAGE_SIZE';end if;
 select count(*) into total from private.catalog_source_companies where p_query='' or position(p_query in name)>0;
 select coalesce(jsonb_agg(to_jsonb(page) order by page.name,page.id),'[]') into items from
 (select id,name,active,stock_identity_state from private.catalog_source_companies where p_query='' or position(p_query in name)>0 order by name,id limit p_limit offset p_offset)page;
 return jsonb_build_object('catalog_version',head::text,'items',items,'total',total,'offset',p_offset,'limit',p_limit);
end$$;
create function public.catalog_editor_company(p_company uuid,p_expected bigint default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;item jsonb;
begin
 perform private.m1_assert_editor();head:=private.catalog_require_reference_head(p_expected);
 select to_jsonb(c)-'source_row' into item from private.catalog_source_companies c where id=p_company;
 if item is null then raise exception 'CATALOG_ENTITY_NOT_FOUND';end if;
 return jsonb_build_object('catalog_version',head::text,'company',item);
end$$;
create function private.catalog_description(p_text text,p_max_chars integer default 2000,p_max_bytes integer default 6000) returns text language plpgsql immutable set search_path='' as $$
begin
 if p_text is null or length(p_text)>p_max_chars or octet_length(p_text)>p_max_bytes then raise exception 'INVALID_CATALOG_TEXT';end if;
 return p_text;
end$$;
create function private.catalog_diff(p_before jsonb,p_after jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare collection text;delta jsonb;result jsonb:='{}';
begin
 foreach collection in array array['sectors','subgroups','companies','memberships','sector_data'] loop
  select jsonb_agg(jsonb_build_object('id',coalesce(previous.id,current.id),'before',previous.data,'after',current.data) order by coalesce(previous.id,current.id)) into delta
  from (select coalesce(entry.value->>'id',entry.value->>'sector_id') id,entry.value data from jsonb_array_elements(coalesce(p_before->collection,'[]')) entry) previous
  full join (select coalesce(entry.value->>'id',entry.value->>'sector_id') id,entry.value data from jsonb_array_elements(coalesce(p_after->collection,'[]')) entry) current using(id)
  where previous.data is distinct from current.data;
  if delta is not null then result:=jsonb_set(result,array[collection],delta,true);end if;
 end loop;
 return result;
end$$;
create function private.catalog_finish_version(p_previous bigint) returns bigint language plpgsql set search_path='' as $$
declare current_head bigint;next_version bigint;
begin
 select version into current_head from private.catalog_head where singleton for update;
 if current_head is distinct from p_previous then raise exception 'STALE_CATALOG';end if;
 select coalesce(max(version),0)+1 into next_version from private.catalog_versions;
 update private.catalog_versions set active=false where active;
 insert into private.catalog_versions(version,active) values(next_version,true);
 update private.sectors set catalog_version=next_version where metadata_kind='USER_REFERENCE_UNVERIFIED';
 update private.catalog_head set version=next_version where singleton;
 perform private.catalog_save_snapshot(next_version);
 return next_version;
end$$;
create function private.catalog_active_parent(p_parent uuid) returns void language plpgsql stable set search_path='' as $$
begin
 if p_parent is null or not exists(select 1 from private.sectors where id=p_parent and active and metadata_kind='USER_REFERENCE_UNVERIFIED' and catalog_kind='PARENT') then raise exception 'INACTIVE_CATALOG_PARENT';end if;
end$$;
create function private.catalog_active_leaf(p_sector uuid) returns void language plpgsql stable set search_path='' as $$
declare head bigint;
begin
 head:=private.catalog_require_reference_head(null);
 if not private.catalog_sector_selectable(p_sector,head,'SYNTHETIC') then raise exception 'INACTIVE_CATALOG_SECTOR';end if;
end$$;
create function public.catalog_editor_index(p_offset integer default 0,p_limit integer default 100) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;items jsonb;
begin
 perform private.m1_assert_editor();head:=private.catalog_require_reference_head(null);
 if p_offset is null or p_offset not between 0 and 100000 or p_limit is null or p_limit not between 1 and 200 then raise exception 'INVALID_PAGE_SIZE';end if;
 select coalesce(jsonb_agg(to_jsonb(page) order by page.catalog_kind,page.display_order,page.id),'[]') into items from
 (select id,name,parent_id,display_order,active,catalog_kind from private.sectors where metadata_kind='USER_REFERENCE_UNVERIFIED'
 order by catalog_kind,display_order,id limit p_limit offset p_offset)page;
 return jsonb_build_object('catalog_version',head::text,'actor_id',auth.uid(),'items',items,'total',(select count(*) from private.sectors where metadata_kind='USER_REFERENCE_UNVERIFIED'),'offset',p_offset,'limit',p_limit);
end$$;
create function private.catalog_string(p_payload jsonb,p_field text,p_default text default null) returns text language plpgsql immutable set search_path='' as $$
begin
 if not p_payload ? p_field then return p_default;end if;
 if jsonb_typeof(p_payload->p_field) is distinct from 'string' then raise exception 'INVALID_CATALOG_TEXT';end if;
 return p_payload->>p_field;
end$$;
create function private.catalog_edit_sector(p_kind text,p_entity uuid,p_payload jsonb,p_head bigint) returns uuid language plpgsql set search_path='' as $$
declare entity uuid:=p_entity;target private.sectors;label text;description text;parent uuid;kind text;ordering integer;affected uuid[];issue_ids uuid[];impact jsonb;
begin
 perform 1 from private.catalog_head where singleton for update;
 perform private.catalog_require_reference_head(p_head);
 if p_kind='SECTOR_CREATE' then
  perform private.catalog_assert_payload(p_payload,array['name','description','parent_id','catalog_kind','display_order'],array['name','catalog_kind']);
  if p_entity is not null then raise exception 'SERVER_ENTITY_ID_REQUIRED';end if;
  kind:=private.catalog_string(p_payload,'catalog_kind');
  if kind not in ('PARENT','LEAF') then raise exception 'INVALID_CATALOG_KIND';end if;
  if (select count(*) from private.sectors where metadata_kind='USER_REFERENCE_UNVERIFIED' and catalog_kind=kind and active)>=(case when kind='PARENT' then 50 else 200 end) then raise exception 'CATALOG_ENTITY_LIMIT';end if;
  label:=private.catalog_label(private.catalog_string(p_payload,'name'));
  description:=private.catalog_description(private.catalog_string(p_payload,'description',''));
  parent:=(p_payload->>'parent_id')::uuid;
  if kind='LEAF' then perform private.catalog_active_parent(parent);elsif parent is not null then raise exception 'INVALID_CATALOG_PARENT';end if;
  if exists(select 1 from private.sectors s where s.metadata_kind='USER_REFERENCE_UNVERIFIED' and s.catalog_kind=kind and normalize(s.name,NFC)=label) then raise exception 'CATALOG_NAME_COLLISION';end if;
  ordering:=private.catalog_order(p_payload->'display_order',0);entity:=gen_random_uuid();
  insert into private.sectors(id,name,description,parent_id,display_order,catalog_version,sample_kind,metadata_kind,catalog_kind)
  values(entity,label,description,parent,ordering,p_head,null,'USER_REFERENCE_UNVERIFIED',kind);
  if kind='LEAF' then insert into private.catalog_sector_data(sector_id) values(entity);end if;
  return entity;
 end if;
 select * into target from private.sectors s where s.id=p_entity and s.metadata_kind='USER_REFERENCE_UNVERIFIED' for update;
 if not found then raise exception 'CATALOG_ENTITY_NOT_FOUND';end if;
 if p_kind='SECTOR_UPDATE' then
  perform private.catalog_assert_payload(p_payload,array['name','description','parent_id','display_order']);
  if p_payload='{}' then raise exception 'INVALID_CATALOG_PAYLOAD';end if;
  if not target.active then raise exception 'CATALOG_ENTITY_INACTIVE';end if;
  label:=private.catalog_label(private.catalog_string(p_payload,'name',target.name));
  description:=private.catalog_description(private.catalog_string(p_payload,'description',target.description));
  parent:=case when p_payload ? 'parent_id' then (p_payload->>'parent_id')::uuid else target.parent_id end;
  if target.catalog_kind='LEAF' then perform private.catalog_active_parent(parent);elsif parent is not null then raise exception 'INVALID_CATALOG_PARENT';end if;
  if exists(select 1 from private.sectors s where s.metadata_kind='USER_REFERENCE_UNVERIFIED' and s.catalog_kind=target.catalog_kind and s.id<>p_entity and normalize(s.name,NFC)=label) then raise exception 'CATALOG_NAME_COLLISION';end if;
  update private.sectors set name=label,description=description,parent_id=parent,display_order=private.catalog_order(p_payload->'display_order',target.display_order) where id=p_entity;
 elsif p_kind='SECTOR_DEACTIVATE' then
  perform private.catalog_assert_payload(p_payload,array['impact_sha256'],array['impact_sha256']);
  if not target.active then raise exception 'CATALOG_ENTITY_INACTIVE';end if;
  select array_agg(id order by id) into affected from private.sectors s where s.metadata_kind='USER_REFERENCE_UNVERIFIED' and (s.id=p_entity or s.parent_id=p_entity);
  issue_ids:=private.catalog_affected_issues(affected);
  perform 1 from private.issues i where i.id=any(issue_ids) order by i.id for update;
  impact:=private.catalog_impact(p_entity);
  if p_payload->>'impact_sha256' is distinct from impact->>'impact_sha256' then raise exception 'CATALOG_IMPACT_CHANGED';end if;
  update private.catalog_memberships set active=false where sector_id=any(affected) and active;
  update private.subgroups set active=false where sector_id=any(affected) and metadata_kind='USER_REFERENCE_UNVERIFIED';
  update private.sectors set active=false where id=any(affected);
  update private.issues set publication_state='CORRECTION_PENDING',revision=revision+1 where id=any(issue_ids) and publication_state='PUBLISHED';
 elsif p_kind='SECTOR_RESTORE' then
  perform private.catalog_assert_payload(p_payload,array['display_order']);
  if target.active then raise exception 'INVALID_CATALOG_STATE';end if;
  if target.catalog_kind='LEAF' then perform private.catalog_active_parent(target.parent_id);end if;
  update private.sectors set active=true,display_order=private.catalog_order(p_payload->'display_order',target.display_order) where id=p_entity;
  -- Restoring metadata never republishes a correction-pending article or silently
  -- reactivates descendant groups/memberships. Each restoration is explicit.
 else raise exception 'CATALOG_OPERATION_NOT_ALLOWED';end if;
 return entity;
end$$;
create or replace function private.catalog_edit_sector(p_kind text,p_entity uuid,p_payload jsonb,p_head bigint) returns uuid language plpgsql set search_path='' as $$
declare entity uuid:=p_entity;target private.sectors;label text;new_description text;parent uuid;kind text;ordering integer;affected uuid[];issue_ids uuid[];impact jsonb;
begin
 perform 1 from private.catalog_head where singleton for update;
 perform private.catalog_require_reference_head(p_head);
 if p_kind='SECTOR_CREATE' then
  perform private.catalog_assert_payload(p_payload,array['name','description','parent_id','catalog_kind','display_order'],array['name','catalog_kind']);
  if p_entity is not null then raise exception 'SERVER_ENTITY_ID_REQUIRED';end if;
  kind:=private.catalog_string(p_payload,'catalog_kind');
  if kind not in ('PARENT','LEAF') then raise exception 'INVALID_CATALOG_KIND';end if;
  if (select count(*) from private.sectors where metadata_kind='USER_REFERENCE_UNVERIFIED' and catalog_kind=kind and active)>=(case when kind='PARENT' then 50 else 200 end) then raise exception 'CATALOG_ENTITY_LIMIT';end if;
  label:=private.catalog_label(private.catalog_string(p_payload,'name'));
  new_description:=private.catalog_description(private.catalog_string(p_payload,'description',''));
  parent:=(p_payload->>'parent_id')::uuid;
  if kind='LEAF' then perform private.catalog_active_parent(parent);elsif parent is not null then raise exception 'INVALID_CATALOG_PARENT';end if;
  if exists(select 1 from private.sectors s where s.metadata_kind='USER_REFERENCE_UNVERIFIED' and s.catalog_kind=kind and normalize(s.name,NFC)=label) then raise exception 'CATALOG_NAME_COLLISION';end if;
  ordering:=private.catalog_order(p_payload->'display_order',0);entity:=gen_random_uuid();
  insert into private.sectors(id,name,description,parent_id,display_order,catalog_version,sample_kind,metadata_kind,catalog_kind)
  values(entity,label,new_description,parent,ordering,p_head,null,'USER_REFERENCE_UNVERIFIED',kind);
  if kind='LEAF' then insert into private.catalog_sector_data(sector_id) values(entity);end if;
  return entity;
 end if;
 select * into target from private.sectors s where s.id=p_entity and s.metadata_kind='USER_REFERENCE_UNVERIFIED' for update;
 if not found then raise exception 'CATALOG_ENTITY_NOT_FOUND';end if;
 if p_kind='SECTOR_UPDATE' then
  perform private.catalog_assert_payload(p_payload,array['name','description','parent_id','display_order']);
  if p_payload='{}' then raise exception 'INVALID_CATALOG_PAYLOAD';end if;
  if not target.active then raise exception 'CATALOG_ENTITY_INACTIVE';end if;
  label:=private.catalog_label(private.catalog_string(p_payload,'name',target.name));
  new_description:=private.catalog_description(private.catalog_string(p_payload,'description',target.description));
  parent:=case when p_payload ? 'parent_id' then (p_payload->>'parent_id')::uuid else target.parent_id end;
  if target.catalog_kind='LEAF' then perform private.catalog_active_parent(parent);elsif parent is not null then raise exception 'INVALID_CATALOG_PARENT';end if;
  if exists(select 1 from private.sectors s where s.metadata_kind='USER_REFERENCE_UNVERIFIED' and s.catalog_kind=target.catalog_kind and s.id<>p_entity and normalize(s.name,NFC)=label) then raise exception 'CATALOG_NAME_COLLISION';end if;
  update private.sectors set name=label,description=new_description,parent_id=parent,display_order=private.catalog_order(p_payload->'display_order',target.display_order) where id=p_entity;
 elsif p_kind='SECTOR_DEACTIVATE' then
  perform private.catalog_assert_payload(p_payload,array['impact_sha256'],array['impact_sha256']);
  if not target.active then raise exception 'CATALOG_ENTITY_INACTIVE';end if;
  select array_agg(id order by id) into affected from private.sectors s where s.metadata_kind='USER_REFERENCE_UNVERIFIED' and (s.id=p_entity or s.parent_id=p_entity);
  issue_ids:=private.catalog_affected_issues(affected);
  perform 1 from private.issues i where i.id=any(issue_ids) order by i.id for update;
  impact:=private.catalog_impact(p_entity);
  if p_payload->>'impact_sha256' is distinct from impact->>'impact_sha256' then raise exception 'CATALOG_IMPACT_CHANGED';end if;
  update private.catalog_memberships set active=false where sector_id=any(affected) and active;
  update private.subgroups set active=false where sector_id=any(affected) and metadata_kind='USER_REFERENCE_UNVERIFIED';
  update private.sectors set active=false where id=any(affected);
  update private.issues set publication_state='CORRECTION_PENDING',revision=revision+1 where id=any(issue_ids) and publication_state='PUBLISHED';
 elsif p_kind='SECTOR_RESTORE' then
  perform private.catalog_assert_payload(p_payload,array['display_order']);
  if target.active then raise exception 'INVALID_CATALOG_STATE';end if;
  if target.catalog_kind='LEAF' then perform private.catalog_active_parent(target.parent_id);end if;
  update private.sectors set active=true,display_order=private.catalog_order(p_payload->'display_order',target.display_order) where id=p_entity;
  -- Restoring metadata never republishes a correction-pending article or silently
  -- reactivates descendant groups/memberships. Each restoration is explicit.
 else raise exception 'CATALOG_OPERATION_NOT_ALLOWED';end if;
 return entity;
end$$;
create or replace function public.m0_update_settings(p_install uuid,p_secret text,p_version integer,p_morning boolean,p_closing boolean,p_favorite boolean,p_sector_ids uuid[]) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 perform private.assert_server();perform private.assert_initialized();
 perform 1 from private.catalog_head where singleton for share;
 perform private.assert_installation(p_install,p_secret,p_version);
 if p_morning is null or p_closing is null or p_favorite is null or p_sector_ids is null then raise exception 'SETTINGS_REQUIRED';end if;
 if cardinality(p_sector_ids)<>(select count(distinct u.sector_id) from unnest(p_sector_ids) as u(sector_id)) then raise exception 'DUPLICATE_OR_NULL_SECTOR';end if;
 if exists(select 1 from unnest(p_sector_ids) as u(sector_id) where not exists(select 1 from private.sectors as s where s.id=u.sector_id and s.active)) then raise exception 'INACTIVE_SECTOR';end if;
 update private.installation_settings set morning_issue=p_morning,closing_issue=p_closing,favorite_sector_issue=p_favorite,sector_ids=p_sector_ids,updated_at=clock_timestamp() where installation_id=p_install;
 return public.m0_get_settings(p_install,p_secret,p_version);
end$$;
alter function private.catalog_impact(uuid) rename to catalog_impact_v1;
create function private.catalog_impact(p_sector uuid) returns jsonb language plpgsql set search_path='' as $$
declare base jsonb;affected uuid[];settings jsonb;settings_count bigint;
begin
 base:=private.catalog_impact_v1(p_sector);
 select array_agg(id order by id) into affected from private.sectors where metadata_kind='USER_REFERENCE_UNVERIFIED' and (id=p_sector or parent_id=p_sector);
 select count(*),coalesce(jsonb_agg(jsonb_build_object('id',installation_id,'sector_ids',sector_ids,'updated_at',updated_at) order by installation_id),'[]') into settings_count,settings
 from private.installation_settings where sector_ids&&affected;
 -- Installation IDs participate only in the digest and never leave this function.
 return base||jsonb_build_object('interest_settings_count',settings_count,'filter_effect','Inactive choices are removed when the current catalog is loaded',
 'impact_sha256',encode(extensions.digest(convert_to(jsonb_build_array(base->>'impact_sha256',settings)::text,'UTF8'),'sha256'),'hex'));
end$$;
alter function private.catalog_edit_sector(text,uuid,jsonb,bigint) rename to catalog_edit_sector_v1;
create function private.catalog_edit_sector(p_kind text,p_entity uuid,p_payload jsonb,p_head bigint) returns uuid language plpgsql set search_path='' as $$
declare affected uuid[];result uuid;
begin
 perform 1 from private.catalog_head where singleton for update;
 if p_kind='SECTOR_DEACTIVATE' then
  select array_agg(id order by id) into affected from private.sectors where metadata_kind='USER_REFERENCE_UNVERIFIED' and (id=p_entity or parent_id=p_entity);
  perform 1 from private.installation_settings where sector_ids&&affected order by installation_id for update;
 end if;
 result:=private.catalog_edit_sector_v1(p_kind,p_entity,p_payload,p_head);
 if p_kind='SECTOR_DEACTIVATE' then
  update private.installation_settings set sector_ids=array(select item from unnest(sector_ids) with ordinality ids(item,n) where not item=any(affected) order by n),updated_at=clock_timestamp() where sector_ids&&affected;
 end if;
 return result;
end$$;
alter table private.catalog_memberships alter constraint catalog_memberships_subgroup_id_sector_id_fkey deferrable initially immediate;
create function private.catalog_edit_group(p_kind text,p_entity uuid,p_payload jsonb) returns uuid language plpgsql set search_path='' as $$
declare target private.subgroups;entity uuid:=p_entity;leaf uuid;label text;new_order integer;
begin
 if p_kind='GROUP_CREATE' then
  perform private.catalog_assert_payload(p_payload,array['sector_id','name','display_order'],array['sector_id','name']);
  if p_entity is not null then raise exception 'SERVER_ENTITY_ID_REQUIRED';end if;
  leaf:=(p_payload->>'sector_id')::uuid;perform private.catalog_active_leaf(leaf);
  label:=private.catalog_label(private.catalog_string(p_payload,'name'));
  if (select count(*) from private.subgroups where sector_id=leaf and metadata_kind='USER_REFERENCE_UNVERIFIED')>=100 then raise exception 'CATALOG_ENTITY_LIMIT';end if;
  if exists(select 1 from private.subgroups where sector_id=leaf and metadata_kind='USER_REFERENCE_UNVERIFIED' and normalize(name,NFC)=label) then raise exception 'CATALOG_NAME_COLLISION';end if;
  entity:=gen_random_uuid();
  insert into private.subgroups(id,sector_id,name,display_order,metadata_kind) values(entity,leaf,label,private.catalog_order(p_payload->'display_order',0),'USER_REFERENCE_UNVERIFIED');
  return entity;
 end if;
 select * into target from private.subgroups where id=p_entity and metadata_kind='USER_REFERENCE_UNVERIFIED' for update;
 if not found then raise exception 'CATALOG_ENTITY_NOT_FOUND';end if;
 if p_kind='GROUP_UPDATE' then
  perform private.catalog_assert_payload(p_payload,array['name','sector_id','display_order']);
  if not target.active then raise exception 'CATALOG_ENTITY_INACTIVE';end if;
  if p_payload='{}' then raise exception 'INVALID_CATALOG_PAYLOAD';end if;
  leaf:=case when p_payload ? 'sector_id' then (p_payload->>'sector_id')::uuid else target.sector_id end;
  perform private.catalog_active_leaf(leaf);
  label:=private.catalog_label(private.catalog_string(p_payload,'name',target.name));
  if exists(select 1 from private.subgroups where sector_id=leaf and metadata_kind='USER_REFERENCE_UNVERIFIED' and id<>p_entity and normalize(name,NFC)=label) then raise exception 'CATALOG_NAME_COLLISION';end if;
  if leaf<>target.sector_id and (select count(*) from private.subgroups where sector_id=leaf and metadata_kind='USER_REFERENCE_UNVERIFIED')>=100 then raise exception 'CATALOG_ENTITY_LIMIT';end if;
  set constraints private.catalog_memberships_subgroup_id_sector_id_fkey deferred;
  update private.subgroups set sector_id=leaf,name=label,display_order=private.catalog_order(p_payload->'display_order',target.display_order) where id=p_entity;
  update private.catalog_memberships set sector_id=leaf where subgroup_id=p_entity;
  set constraints private.catalog_memberships_subgroup_id_sector_id_fkey immediate;
 elsif p_kind='GROUP_DEACTIVATE' then
  perform private.catalog_assert_payload(p_payload,'{}');
  if not target.active then raise exception 'CATALOG_ENTITY_INACTIVE';end if;
  update private.catalog_memberships set active=false where subgroup_id=p_entity and active;
  update private.subgroups set active=false where id=p_entity;
 elsif p_kind='GROUP_RESTORE' then
  perform private.catalog_assert_payload(p_payload,'{}');
  if target.active then raise exception 'INVALID_CATALOG_STATE';end if;
  perform private.catalog_active_leaf(target.sector_id);
  update private.subgroups set active=true where id=p_entity;
 else raise exception 'CATALOG_OPERATION_NOT_ALLOWED';end if;
 return entity;
end$$;
create function private.catalog_edit_company(p_kind text,p_entity uuid,p_payload jsonb) returns uuid language plpgsql set search_path='' as $$
declare target private.catalog_source_companies;entity uuid:=p_entity;label text;new_description text;direct jsonb;industry jsonb;
begin
 if p_kind='COMPANY_CREATE' then
  perform private.catalog_assert_payload(p_payload,array['name','search_description','direct_terms','industry_terms'],array['name']);
  if p_entity is not null then raise exception 'SERVER_ENTITY_ID_REQUIRED';end if;
  if (select count(*) from private.catalog_source_companies)>=3000 then raise exception 'CATALOG_ENTITY_LIMIT';end if;
  label:=private.catalog_label(private.catalog_string(p_payload,'name'));
  if exists(select 1 from private.catalog_source_companies where normalize(name,NFC)=label) then raise exception 'CATALOG_NAME_COLLISION';end if;
  entity:=gen_random_uuid();
  insert into private.catalog_source_companies(id,name,search_description,direct_keywords,industry_keywords) values(entity,label,
   private.catalog_description(private.catalog_string(p_payload,'search_description','')),
   private.catalog_terms(coalesce(p_payload->'direct_terms','[]')),private.catalog_terms(coalesce(p_payload->'industry_terms','[]')));
  return entity;
 end if;
 select * into target from private.catalog_source_companies where id=p_entity for update;
 if not found then raise exception 'CATALOG_ENTITY_NOT_FOUND';end if;
 if p_kind='COMPANY_UPDATE' then
  perform private.catalog_assert_payload(p_payload,array['name','search_description','direct_terms','industry_terms']);
  if p_payload='{}' then raise exception 'INVALID_CATALOG_PAYLOAD';end if;
  if not target.active then raise exception 'CATALOG_ENTITY_INACTIVE';end if;
  label:=private.catalog_label(private.catalog_string(p_payload,'name',target.name));
  if exists(select 1 from private.catalog_source_companies where id<>p_entity and normalize(name,NFC)=label) then raise exception 'CATALOG_NAME_COLLISION';end if;
  new_description:=private.catalog_description(private.catalog_string(p_payload,'search_description',target.search_description));
  direct:=case when p_payload ? 'direct_terms' then private.catalog_terms(p_payload->'direct_terms') else target.direct_keywords end;
  industry:=case when p_payload ? 'industry_terms' then private.catalog_terms(p_payload->'industry_terms') else target.industry_keywords end;
  update private.catalog_source_companies set name=label,search_description=new_description,direct_keywords=direct,industry_keywords=industry where id=p_entity;
 elsif p_kind='COMPANY_DEACTIVATE' then
  perform private.catalog_assert_payload(p_payload,'{}');
  if not target.active then raise exception 'CATALOG_ENTITY_INACTIVE';end if;
  update private.catalog_memberships set active=false where source_company_ref=p_entity and active;
  update private.catalog_source_companies set active=false where id=p_entity;
 elsif p_kind='COMPANY_RESTORE' then
  perform private.catalog_assert_payload(p_payload,'{}');
  if target.active then raise exception 'INVALID_CATALOG_STATE';end if;
  update private.catalog_source_companies set active=true where id=p_entity;
 else raise exception 'CATALOG_OPERATION_NOT_ALLOWED';end if;
 return entity;
end$$;
create function private.catalog_membership_context(p_leaf uuid,p_group uuid,p_company uuid) returns void language plpgsql set search_path='' as $$
begin
 perform private.catalog_active_leaf(p_leaf);
 if not exists(select 1 from private.catalog_source_companies where id=p_company and active) then raise exception 'CATALOG_COMPANY_INACTIVE';end if;
 if p_group is not null and not exists(select 1 from private.subgroups where id=p_group and sector_id=p_leaf and active and metadata_kind='USER_REFERENCE_UNVERIFIED') then raise exception 'INVALID_CATALOG_GROUP';end if;
end$$;
create function private.catalog_edit_membership(p_kind text,p_entity uuid,p_payload jsonb) returns uuid language plpgsql set search_path='' as $$
declare target private.catalog_memberships;entity uuid:=p_entity;leaf uuid;grp uuid;company uuid;new_role text;
begin
 if p_kind='MEMBERSHIP_CREATE' then
  perform private.catalog_assert_payload(p_payload,array['sector_id','subgroup_id','source_company_ref','role','display_order'],array['sector_id','source_company_ref','role']);
  if p_entity is not null then raise exception 'SERVER_ENTITY_ID_REQUIRED';end if;
  leaf:=(p_payload->>'sector_id')::uuid;grp:=(p_payload->>'subgroup_id')::uuid;company:=(p_payload->>'source_company_ref')::uuid;
  perform private.catalog_membership_context(leaf,grp,company);
  if (select count(*) from private.catalog_memberships where sector_id=leaf)>=2000 then raise exception 'CATALOG_ENTITY_LIMIT';end if;
  if exists(select 1 from private.catalog_memberships where sector_id=leaf and subgroup_id is not distinct from grp and source_company_ref=company) then raise exception 'CATALOG_MEMBERSHIP_EXISTS';end if;
  entity:=gen_random_uuid();new_role:=private.catalog_description(private.catalog_string(p_payload,'role'),600,2000);
  insert into private.catalog_memberships(id,sector_id,subgroup_id,source_company_ref,role,display_order) values(entity,leaf,grp,company,new_role,private.catalog_order(p_payload->'display_order',0));
  return entity;
 end if;
 select * into target from private.catalog_memberships where id=p_entity for update;
 if not found then raise exception 'CATALOG_ENTITY_NOT_FOUND';end if;
 if p_kind='MEMBERSHIP_UPDATE' then
  perform private.catalog_assert_payload(p_payload,array['sector_id','subgroup_id','role','display_order']);
  if p_payload='{}' then raise exception 'INVALID_CATALOG_PAYLOAD';end if;
  if not target.active then raise exception 'CATALOG_ENTITY_INACTIVE';end if;
  leaf:=case when p_payload ? 'sector_id' then (p_payload->>'sector_id')::uuid else target.sector_id end;
  grp:=case when p_payload ? 'subgroup_id' then (p_payload->>'subgroup_id')::uuid else target.subgroup_id end;
  perform private.catalog_membership_context(leaf,grp,target.source_company_ref);
  if exists(select 1 from private.catalog_memberships where id<>p_entity and sector_id=leaf and subgroup_id is not distinct from grp and source_company_ref=target.source_company_ref) then raise exception 'CATALOG_MEMBERSHIP_EXISTS';end if;
  new_role:=private.catalog_description(private.catalog_string(p_payload,'role',coalesce(target.role,'')),600,2000);
  update private.catalog_memberships set sector_id=leaf,subgroup_id=grp,role=new_role,display_order=private.catalog_order(p_payload->'display_order',target.display_order) where id=p_entity;
 elsif p_kind='MEMBERSHIP_DEACTIVATE' then
  perform private.catalog_assert_payload(p_payload,'{}');
  if not target.active then raise exception 'CATALOG_ENTITY_INACTIVE';end if;
  update private.catalog_memberships set active=false where id=p_entity;
 elsif p_kind='MEMBERSHIP_RESTORE' then
  perform private.catalog_assert_payload(p_payload,'{}');
  if target.active then raise exception 'INVALID_CATALOG_STATE';end if;
  perform private.catalog_membership_context(target.sector_id,target.subgroup_id,target.source_company_ref);
  update private.catalog_memberships set active=true where id=p_entity;
 else raise exception 'CATALOG_OPERATION_NOT_ALLOWED';end if;
 return entity;
end$$;
create function private.catalog_edit_keywords(p_entity uuid,p_payload jsonb) returns uuid language plpgsql set search_path='' as $$
declare term_kind text;replacement jsonb;entry jsonb;retained jsonb;
begin
 perform private.catalog_assert_payload(p_payload,array['keyword_kind','terms'],array['keyword_kind','terms']);
 perform private.catalog_active_leaf(p_entity);
 term_kind:=private.catalog_string(p_payload,'keyword_kind');
 if term_kind not in ('INDUSTRY','CORE','ADDITIONAL') then raise exception 'INVALID_CATALOG_KEYWORD_KIND';end if;
 select coalesce(jsonb_agg(item.value order by item.n),'[]') into retained from private.catalog_sector_data d cross join lateral jsonb_array_elements(d.keywords) with ordinality item(value,n) where d.sector_id=p_entity and private.catalog_keyword_kind(item.value)<>term_kind;
 replacement:='[]';
 for entry in select value from jsonb_array_elements(private.catalog_terms(p_payload->'terms')) loop replacement:=replacement||jsonb_build_array(entry||jsonb_build_object('kind',term_kind));end loop;
 update private.catalog_sector_data set keywords=retained||replacement where sector_id=p_entity;
 return p_entity;
end$$;
create function private.catalog_reorder(p_payload jsonb) returns void language plpgsql set search_path='' as $$
declare scope text;parent uuid;grp uuid;ids uuid[];expected uuid[];
begin
 perform private.catalog_assert_payload(p_payload,array['scope','parent_id','subgroup_id','ids'],array['scope','ids']);
 scope:=private.catalog_string(p_payload,'scope');parent:=(p_payload->>'parent_id')::uuid;grp:=(p_payload->>'subgroup_id')::uuid;
 if jsonb_typeof(p_payload->'ids') is distinct from 'array' or jsonb_array_length(p_payload->'ids')>2000 or exists(select 1 from jsonb_array_elements(p_payload->'ids') v where jsonb_typeof(v)<>'string') then raise exception 'INVALID_CATALOG_ORDER';end if;
 select coalesce(array_agg(value::uuid order by n),'{}') into ids from jsonb_array_elements_text(p_payload->'ids') with ordinality v(value,n);
 if cardinality(ids)<>(select count(distinct x) from unnest(ids) x) then raise exception 'INVALID_CATALOG_ORDER';end if;
 if scope='PARENTS' then
  if parent is not null or grp is not null then raise exception 'INVALID_CATALOG_PARENT';end if;
  select coalesce(array_agg(id),'{}') into expected from private.sectors where active and catalog_kind='PARENT' and metadata_kind='USER_REFERENCE_UNVERIFIED';
 elsif scope='SECTORS' then
  perform private.catalog_active_parent(parent);
  if grp is not null then raise exception 'INVALID_CATALOG_GROUP';end if;
  select coalesce(array_agg(id),'{}') into expected from private.sectors where active and parent_id=parent and metadata_kind='USER_REFERENCE_UNVERIFIED';
 elsif scope='GROUPS' then
  perform private.catalog_active_leaf(parent);
  if grp is not null then raise exception 'INVALID_CATALOG_GROUP';end if;
  select coalesce(array_agg(id),'{}') into expected from private.subgroups where active and sector_id=parent and metadata_kind='USER_REFERENCE_UNVERIFIED';
 elsif scope='MEMBERSHIPS' then
  perform private.catalog_active_leaf(parent);
  select coalesce(array_agg(id),'{}') into expected from private.catalog_memberships where active and sector_id=parent and subgroup_id is not distinct from grp;
 else raise exception 'INVALID_CATALOG_ORDER';end if;
 if cardinality(ids)<>cardinality(expected) or not ids@>expected then raise exception 'INCOMPLETE_CATALOG_ORDER';end if;
 if scope in ('PARENTS','SECTORS') then update private.sectors s set display_order=seq.n::integer from unnest(ids) with ordinality seq(id,n) where s.id=seq.id;
 elsif scope='GROUPS' then update private.subgroups s set display_order=seq.n::integer from unnest(ids) with ordinality seq(id,n) where s.id=seq.id;
 else update private.catalog_memberships s set display_order=seq.n::integer from unnest(ids) with ordinality seq(id,n) where s.id=seq.id;end if;
end$$;
create function private.catalog_request_hash(p_expected bigint,p_kind text,p_entity uuid,p_payload jsonb) returns text language sql immutable set search_path='' as $$
 select encode(extensions.digest(convert_to(jsonb_build_object('expected_version',p_expected,'kind',p_kind,'entity_id',p_entity,'payload',p_payload)::text,'UTF8'),'sha256'),'hex')
$$;
create function public.catalog_apply(p_expected bigint,p_operation_key text,p_kind text,p_entity uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid;head bigint;request_hash text;existing private.catalog_operations;before_doc jsonb;delta jsonb;entity uuid;next_version bigint;result jsonb;error_code text;
begin
 perform private.m1_assert_editor();actor:=auth.uid();
 -- Malformed framing/auth failures are not a durable not-applied receipt.
 if p_operation_key is null or p_operation_key!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or p_expected is null or p_expected<1 or p_kind is null or length(p_kind)>60 or p_payload is null or pg_column_size(p_payload)>131072 then raise exception 'INVALID_CATALOG_REQUEST';end if;
 request_hash:=private.catalog_request_hash(p_expected,p_kind,p_entity,p_payload);
 select version into head from private.catalog_head where singleton for update;
 perform private.m1_assert_editor();
 select * into existing from private.catalog_operations where operation_key=p_operation_key;
 if found then
  if existing.actor_id<>actor or existing.payload_sha256<>request_hash then raise exception 'EFFECT_PAYLOAD_CONFLICT';end if;
  return existing.result;
 end if;
 begin
  perform private.catalog_require_reference_head(p_expected);
  before_doc:=private.catalog_document();
  if p_kind=any(array['SECTOR_CREATE','SECTOR_UPDATE','SECTOR_DEACTIVATE','SECTOR_RESTORE']) then entity:=private.catalog_edit_sector(p_kind,p_entity,p_payload,head);
  elsif p_kind=any(array['GROUP_CREATE','GROUP_UPDATE','GROUP_DEACTIVATE','GROUP_RESTORE']) then entity:=private.catalog_edit_group(p_kind,p_entity,p_payload);
  elsif p_kind=any(array['COMPANY_CREATE','COMPANY_UPDATE','COMPANY_DEACTIVATE','COMPANY_RESTORE']) then entity:=private.catalog_edit_company(p_kind,p_entity,p_payload);
  elsif p_kind=any(array['MEMBERSHIP_CREATE','MEMBERSHIP_UPDATE','MEMBERSHIP_DEACTIVATE','MEMBERSHIP_RESTORE']) then entity:=private.catalog_edit_membership(p_kind,p_entity,p_payload);
  elsif p_kind='SECTOR_KEYWORDS' then entity:=private.catalog_edit_keywords(p_entity,p_payload);
  elsif p_kind='REORDER' then
   if p_entity is not null then raise exception 'SERVER_ENTITY_ID_REQUIRED';end if;
   perform private.catalog_reorder(p_payload);
  else raise exception 'CATALOG_OPERATION_NOT_ALLOWED';end if;
  delta:=private.catalog_diff(before_doc,private.catalog_document());
  if delta='{}' then raise exception 'CATALOG_NO_CHANGE';end if;
  next_version:=private.catalog_finish_version(head);
  result:=jsonb_build_object('status','APPLIED','operation_key',p_operation_key,'request_sha256',request_hash,'actor_id',actor,'entity_id',entity,'catalog_version',next_version::text);
  insert into private.audits(actor_id,action,entity_id,details) values(actor::text,'CATALOG_'||p_kind,coalesce(entity::text,next_version::text),jsonb_build_object('operation_key',p_operation_key,'request_sha256',request_hash,'previous_version',head::text,'catalog_version',next_version::text,'diff',delta));
  insert into private.outbox(event_type,effect_key,payload) values('CATALOG_CHANGED','catalog:operation:'||p_operation_key,jsonb_build_object('catalog_version',next_version::text,'operation_key',p_operation_key,'metadata_kind','USER_REFERENCE_UNVERIFIED','catalog_request_hash',request_hash));
 exception
  when raise_exception then
   error_code:=sqlerrm;
   if not error_code=any(array['STALE_CATALOG','CATALOG_ENTITY_LIMIT','INVALID_CATALOG_PAYLOAD','CATALOG_FIELD_NOT_ALLOWED','CATALOG_FIELD_REQUIRED','SERVER_ENTITY_ID_REQUIRED','INVALID_CATALOG_KIND','INVALID_CATALOG_PARENT','CATALOG_NAME_COLLISION','CATALOG_ENTITY_NOT_FOUND','CATALOG_ENTITY_INACTIVE','CATALOG_IMPACT_CHANGED','INVALID_CATALOG_STATE','CATALOG_OPERATION_NOT_ALLOWED','INACTIVE_CATALOG_PARENT','INACTIVE_CATALOG_SECTOR','INVALID_CATALOG_TEXT','INVALID_CATALOG_ORDER','INVALID_CATALOG_KEYWORDS','CATALOG_COMPANY_INACTIVE','INVALID_CATALOG_GROUP','CATALOG_MEMBERSHIP_EXISTS','INVALID_CATALOG_KEYWORD_KIND','INCOMPLETE_CATALOG_ORDER','CATALOG_NO_CHANGE']) then raise;end if;
   result:=jsonb_build_object('status','REJECTED','operation_key',p_operation_key,'request_sha256',request_hash,'actor_id',actor,'catalog_version',head::text,'error',error_code,'not_applied',true);
  when invalid_text_representation or numeric_value_out_of_range or not_null_violation or check_violation or unique_violation or foreign_key_violation then
   result:=jsonb_build_object('status','REJECTED','operation_key',p_operation_key,'request_sha256',request_hash,'actor_id',actor,'catalog_version',head::text,'error','CATALOG_VALUE_REJECTED','not_applied',true);
 end;
 -- A REJECTED journal is committed outside the mutation subtransaction. A
 -- delayed retry can never apply an intent that was definitively rejected.
 insert into private.catalog_operations(operation_key,actor_id,payload_sha256,version,result) values(p_operation_key,actor,request_hash,case when result->>'status'='APPLIED' then next_version else head end,result);
 return result;
end$$;
create function public.catalog_operation_status(p_expected bigint,p_operation_key text,p_kind text,p_entity uuid,p_payload jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare existing private.catalog_operations;request_hash text;
begin
 perform private.m1_assert_editor();
 if p_operation_key is null or length(p_operation_key)>200 or p_payload is null or pg_column_size(p_payload)>131072 then raise exception 'INVALID_CATALOG_REQUEST';end if;
 request_hash:=private.catalog_request_hash(p_expected,p_kind,p_entity,p_payload);
 select * into existing from private.catalog_operations where operation_key=p_operation_key;
 if not found then return jsonb_build_object('status','UNKNOWN','operation_key',p_operation_key,'request_sha256',request_hash,'actor_id',auth.uid());end if;
 if existing.actor_id<>auth.uid() or existing.payload_sha256<>request_hash then raise exception 'EFFECT_PAYLOAD_CONFLICT';end if;
 return existing.result;
end$$;
create or replace function private.catalog_tree(p_head bigint) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('catalog_version',p_head::text,'metadata_kind','USER_REFERENCE_UNVERIFIED','parents',coalesce(jsonb_agg(
 jsonb_build_object('id',parent.id,'name',parent.name,'order',parent.display_order,'sectors',
 (select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'parent_id',s.parent_id,'order',s.display_order) order by s.display_order,s.id),'[]')
 from private.sectors s where s.parent_id=parent.id and private.catalog_sector_selectable(s.id,p_head,'SYNTHETIC')))
 order by parent.display_order,parent.id),'[]'))
 from private.sectors parent where parent.metadata_kind='USER_REFERENCE_UNVERIFIED' and parent.catalog_kind='PARENT' and parent.active and parent.catalog_version=p_head
$$;
create function public.catalog_public_sector_page(p_sector uuid,p_expected bigint default null,p_offset integer default 0,p_limit integer default 50) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;sector private.sectors;groups jsonb;page_ids uuid[];total bigint;ungrouped jsonb;
begin
 head:=private.catalog_require_reference_head(p_expected);
 if p_offset is null or p_offset not between 0 and 100000 or p_limit is null or p_limit not between 1 and 50 then raise exception 'INVALID_PAGE_SIZE';end if;
 if not private.catalog_sector_selectable(p_sector,head,'SYNTHETIC') then return jsonb_build_object('state','NOT_FOUND','catalog_version',head::text);end if;
 select * into sector from private.sectors where id=p_sector;
 select count(*) into total from private.catalog_memberships m join private.catalog_source_companies c on c.id=m.source_company_ref and c.active where m.sector_id=p_sector and m.active;
 select coalesce(array_agg(id),'{}') into page_ids from(select m.id from private.catalog_memberships m join private.catalog_source_companies c on c.id=m.source_company_ref and c.active
 left join private.subgroups g on g.id=m.subgroup_id where m.sector_id=p_sector and m.active and (m.subgroup_id is null or g.active)
 order by coalesce(g.display_order,-1),g.id nulls first,m.display_order,m.id limit p_limit offset p_offset)page;
 select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'order',g.display_order,'members',
 (select coalesce(jsonb_agg(item.value order by item.n),'[]') from jsonb_array_elements(private.catalog_public_members(p_sector,g.id)) with ordinality item(value,n) where (item.value->>'membership_id')::uuid=any(page_ids))) order by g.display_order,g.id),'[]') into groups
 from private.subgroups g where g.sector_id=p_sector and g.active and g.metadata_kind='USER_REFERENCE_UNVERIFIED';
 select coalesce(jsonb_agg(item.value order by item.n),'[]') into ungrouped from jsonb_array_elements(private.catalog_public_members(p_sector,null)) with ordinality item(value,n) where (item.value->>'membership_id')::uuid=any(page_ids);
 return jsonb_build_object('state','AVAILABLE','catalog_version',head::text,'id',sector.id,'name',sector.name,'description',sector.description,'parent_id',sector.parent_id,'metadata_kind',sector.metadata_kind,
 'groups',groups,'ungrouped_members',ungrouped,'offset',p_offset,'total_memberships',total,'next_offset',case when p_offset+cardinality(page_ids)<total then p_offset+cardinality(page_ids) else null end);
end$$;
create or replace function public.catalog_public_sector(p_sector uuid,p_expected bigint default null) returns jsonb language sql stable security definer set search_path='' as $$
 select public.catalog_public_sector_page(p_sector,p_expected,0,50)
$$;
create function private.catalog_compact_terms(p_terms jsonb) returns jsonb language sql immutable set search_path='' as $$
 select coalesce(jsonb_agg(coalesce(item.value->'raw',item.value->'value') order by item.n),'[]') from jsonb_array_elements(p_terms) with ordinality item(value,n)
$$;
create or replace function public.catalog_editor_company(p_company uuid,p_expected bigint default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;item jsonb;
begin
 perform private.m1_assert_editor();head:=private.catalog_require_reference_head(p_expected);
 select jsonb_build_object('id',id,'name',name,'search_description',search_description,'direct_terms',private.catalog_compact_terms(direct_keywords),'industry_terms',private.catalog_compact_terms(industry_keywords),'active',active,'stock_identity_state',stock_identity_state,'metadata_kind',metadata_kind) into item from private.catalog_source_companies where id=p_company;
 if item is null then raise exception 'CATALOG_ENTITY_NOT_FOUND';end if;
 return jsonb_build_object('catalog_version',head::text,'company',item);
end$$;
alter function public.catalog_editor_sector(uuid,bigint,integer,integer) rename to catalog_editor_sector_v1;
create function public.catalog_editor_sector(p_sector uuid,p_expected bigint default null,p_offset integer default 0,p_limit integer default 50) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result jsonb;settings jsonb;terms jsonb;kind text;
begin
 perform private.m1_assert_editor();
 result:=public.catalog_editor_sector_v1(p_sector,p_expected,p_offset,p_limit);settings:='{}';
 foreach kind in array array['INDUSTRY','CORE','ADDITIONAL'] loop
  select private.catalog_compact_terms(coalesce(jsonb_agg(item.value order by item.n),'[]')) into terms from private.catalog_sector_data d cross join lateral jsonb_array_elements(d.keywords) with ordinality item(value,n) where d.sector_id=p_sector and private.catalog_keyword_kind(item.value)=kind;
  settings:=jsonb_set(settings,array[kind],terms,true);
 end loop;
 return result||jsonb_build_object('keyword_settings',settings);
end$$;
create index news_public_date_id_order on public.news_public(first_published_at desc,issue_id asc) where publication_state='PUBLISHED';
create index catalog_impact_sector_version on private.impacts(sector_id,version_id);
create function public.catalog_public_articles(p_expected bigint,p_sectors uuid[] default '{}',p_period text default 'TODAY',p_limit integer default 20,p_as_of timestamptz default null,p_last_time timestamptz default null,p_last_id uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;cutoff timestamptz;local_day timestamp;start_at timestamptz;end_at timestamptz;items jsonb;next_item jsonb;
begin
 head:=private.catalog_require_reference_head(p_expected);cutoff:=coalesce(p_as_of,statement_timestamp());local_day:=date_trunc('day',cutoff at time zone 'Asia/Seoul');
 if cutoff>statement_timestamp()+interval '5 seconds' or cutoff<timestamp with time zone '2000-01-01 00:00:00+00' or p_limit is null or p_limit not between 1 and 50 or p_sectors is null or cardinality(p_sectors)>200 or cardinality(p_sectors)<>(select count(distinct id) from unnest(p_sectors)id)
 or (p_last_time is null)<>(p_last_id is null) or p_last_time>cutoff then raise exception 'INVALID_CURSOR_CONTEXT';end if;
 if exists(select 1 from unnest(p_sectors)id where not private.catalog_sector_selectable(id,head,'SYNTHETIC')) then raise exception 'STALE_CATALOG';end if;
 if p_period='TODAY' then start_at:=local_day at time zone 'Asia/Seoul';end_at:=(local_day+interval '1 day') at time zone 'Asia/Seoul';
 elsif p_period='YESTERDAY' then start_at:=(local_day-interval '1 day') at time zone 'Asia/Seoul';end_at:=local_day at time zone 'Asia/Seoul';
 elsif p_period='THIS_WEEK' then start_at:=date_trunc('week',local_day) at time zone 'Asia/Seoul';end_at:=(date_trunc('week',local_day)+interval '1 week') at time zone 'Asia/Seoul';
 elsif p_period='LAST_WEEK' then start_at:=(date_trunc('week',local_day)-interval '1 week') at time zone 'Asia/Seoul';end_at:=date_trunc('week',local_day) at time zone 'Asia/Seoul';
 elsif p_period='THIS_MONTH' then start_at:=date_trunc('month',local_day) at time zone 'Asia/Seoul';end_at:=(date_trunc('month',local_day)+interval '1 month') at time zone 'Asia/Seoul';
 elsif p_period='LAST_MONTH' then start_at:=(date_trunc('month',local_day)-interval '1 month') at time zone 'Asia/Seoul';end_at:=date_trunc('month',local_day) at time zone 'Asia/Seoul';
 else raise exception 'INVALID_CURSOR_CONTEXT';end if;
 select coalesce(jsonb_agg(to_jsonb(page) order by page.first_published_at desc,page.issue_id),'[]') into items from(
  select n.issue_id,n.version_id,n.title,n.summary,n.first_published_at,n.material_change_at,n.sample_kind,v.public_body->>'article_kind' article_kind,s.id sector_id,s.name sector_name,s.metadata_kind,
   case when s.metadata_kind='SYNTHETIC_FIXTURE' then true else false end legacy_sector
  from public.news_public n join private.issues i on i.id=n.issue_id join private.article_versions v on v.id=n.version_id left join private.sectors s on s.id=i.primary_sector_id and s.active
  where n.publication_state='PUBLISHED' and private.m1_current_evidence(n.issue_id) and n.first_published_at>=start_at and n.first_published_at<end_at and n.first_published_at<=cutoff
   and (cardinality(p_sectors)=0 or exists(select 1 from private.impacts z where z.version_id=v.id and z.sector_id=any(p_sectors)))
   and (p_last_time is null or n.first_published_at<p_last_time or n.first_published_at=p_last_time and n.issue_id>p_last_id)
  order by n.first_published_at desc,n.issue_id asc limit p_limit+1
 )page;
 if jsonb_array_length(items)>p_limit then
  items:=items- p_limit;next_item:=items->(p_limit-1);
 end if;
 return jsonb_build_object('catalog_version',head::text,'as_of',cutoff,'period',p_period,'range_start',start_at,'range_end',end_at,'items',items,
 'next',case when next_item is not null then jsonb_build_object('last_time',next_item->'first_published_at','last_id',next_item->'issue_id') else null end);
end$$;
create or replace function private.catalog_terms(p_terms jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare term jsonb;result jsonb:='[]';label text;
begin
 if jsonb_typeof(p_terms) is distinct from 'array' or jsonb_array_length(p_terms)>200 or octet_length(p_terms::text)>16384 then raise exception 'INVALID_CATALOG_KEYWORDS';end if;
 for term in select value from jsonb_array_elements(p_terms) loop
  if jsonb_typeof(term)<>'string' then raise exception 'INVALID_CATALOG_KEYWORDS';end if;
  label:=private.catalog_label(term#>>'{}',100);
  if label~E'[\n\r]' then raise exception 'INVALID_CATALOG_KEYWORDS';end if;
  result:=result||jsonb_build_array(jsonb_build_object('raw',term#>>'{}','value',btrim(term#>>'{}'),'comparisonKey',label,'origin','ADMIN'));
 end loop;
 return result;
end$$;
create or replace function public.catalog_public_sector_page(p_sector uuid,p_expected bigint default null,p_offset integer default 0,p_limit integer default 50) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;sector private.sectors;groups jsonb;page_ids uuid[];total bigint;ungrouped jsonb;
begin
 head:=private.catalog_require_reference_head(p_expected);
 if p_offset is null or p_offset not between 0 and 100000 or p_limit is null or p_limit not between 1 and 50 then raise exception 'INVALID_PAGE_SIZE';end if;
 if not private.catalog_sector_selectable(p_sector,head,'SYNTHETIC') then return jsonb_build_object('state','NOT_FOUND','catalog_version',head::text);end if;
 select * into sector from private.sectors where id=p_sector;
 select count(*) into total from private.catalog_memberships m join private.catalog_source_companies c on c.id=m.source_company_ref and c.active where m.sector_id=p_sector and m.active;
 select coalesce(array_agg(id),'{}') into page_ids from(select m.id from private.catalog_memberships m join private.catalog_source_companies c on c.id=m.source_company_ref and c.active
 left join private.subgroups g on g.id=m.subgroup_id where m.sector_id=p_sector and m.active and (m.subgroup_id is null or g.active)
 order by coalesce(g.display_order,-1),g.id nulls first,m.display_order,m.id limit p_limit offset p_offset)page;
 select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'order',g.display_order,'members',
 (select coalesce(jsonb_agg(item.value order by item.n),'[]') from jsonb_array_elements(private.catalog_public_members(p_sector,g.id)) with ordinality item(value,n) where (item.value->>'membership_id')::uuid=any(page_ids))) order by g.display_order,g.id),'[]') into groups
 from private.subgroups g where g.sector_id=p_sector and g.active and g.metadata_kind='USER_REFERENCE_UNVERIFIED' and exists(select 1 from private.catalog_memberships m where m.subgroup_id=g.id and m.id=any(page_ids));
 select coalesce(jsonb_agg(item.value order by item.n),'[]') into ungrouped from jsonb_array_elements(private.catalog_public_members(p_sector,null)) with ordinality item(value,n) where (item.value->>'membership_id')::uuid=any(page_ids);
 return jsonb_build_object('state','AVAILABLE','catalog_version',head::text,'id',sector.id,'name',sector.name,'description',sector.description,'parent_id',sector.parent_id,'metadata_kind',sector.metadata_kind,
 'groups',groups,'ungrouped_members',ungrouped,'offset',p_offset,'total_memberships',total,'next_offset',case when p_offset+cardinality(page_ids)<total then p_offset+cardinality(page_ids) else null end);
end$$;
create function private.catalog_projected_bounds() returns void language plpgsql set search_path='' as $$
begin
 if (select count(*) from private.sectors where active and metadata_kind='USER_REFERENCE_UNVERIFIED' and catalog_kind='PARENT')>50
 or (select count(*) from private.sectors where active and metadata_kind='USER_REFERENCE_UNVERIFIED' and catalog_kind='LEAF')>200
 or exists(select 1 from private.subgroups where metadata_kind='USER_REFERENCE_UNVERIFIED' group by sector_id having count(*)>100)
 or exists(select 1 from private.catalog_memberships group by sector_id having count(*)>2000) then raise exception 'CATALOG_ENTITY_LIMIT';end if;
end$$;
alter function private.catalog_finish_version(bigint) rename to catalog_finish_version_v1;
create function private.catalog_finish_version(p_previous bigint) returns bigint language plpgsql set search_path='' as $$
begin perform private.catalog_projected_bounds();return private.catalog_finish_version_v1(p_previous);end$$;
create or replace function public.m1_save_draft(p_issue uuid,p_expected_revision bigint,p_content jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
begin
