if (select pg_get_userbyid(relowner) from pg_class where oid='supabase_migrations.schema_migrations'::regclass)<>'postgres' or (select pg_get_userbyid(nspowner) from pg_namespace where nspname='supabase_migrations')<>'postgres' or exists(select 1 from pg_class where oid='supabase_migrations.schema_migrations'::regclass and (relrowsecurity or relforcerowsecurity)) then raise exception 'HISTORY_OWNER_SECURITY';end if;
 if exists(select 1 from pg_trigger where tgrelid='supabase_migrations.schema_migrations'::regclass and not tgisinternal) or exists(select 1 from pg_rewrite where ev_class='supabase_migrations.schema_migrations'::regclass) then raise exception 'HISTORY_SIDE_EFFECT_SURFACE';end if;
