 foreach api_role in array array['anon','authenticated','service_role'] loop if has_schema_privilege(api_role,'supabase_migrations','USAGE,CREATE') or has_table_privilege(api_role,'supabase_migrations.schema_migrations','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') or has_any_column_privilege(api_role,'supabase_migrations.schema_migrations','SELECT,INSERT,UPDATE,REFERENCES') then raise exception 'HISTORY_API_ACCESS';end if;end loop;
