 if jsonb_array_length(current_meta->'relations')<>58 or (select count(*) from private.catalog_head)<>1 or (select to_jsonb(x) from private.catalog_head x) is distinct from '{"singleton":true,"version":1}'::jsonb or (select count(*) from private.catalog_snapshots)<>1 or not exists(select 1 from private.catalog_snapshots where version=1 and usage_scope='LEGACY_FIXTURE' and document='{"sectors":[]}'::jsonb and sha256=encode(extensions.digest(convert_to(document::text,'UTF8'),'sha256'),'hex') and created_at=now()) or (select count(*) from private.catalog_approvals)<>1 or (select to_jsonb(x) from private.catalog_approvals x) is distinct from '{"version":1,"state":"APPROVED"}'::jsonb then raise exception 'CATALOG_DERIVED_SEED';end if;
